insert into public.theories (id, question_id, legacy_author_key, identity_mode, thesis, paragraphs, change_mind, status, dmz_pick, starter, needs_review, legacy_url, created_at, published_at) values
  ('l6642', 'what-will-trump-do-if-he-loses-the-election', 'chan-lee', 'name', null, array['While the hype is exciting and fascinating to witness, the post-election reality will likely underwhelm. Trump will lose by a substantial margin, with the loss compounding as more and more ballots are counted. His attempt to claim victory will be short-lived, and the violence will not be cohesive and will not gain much traction. Ultimately, more so than trying to spite democrats, Trump will spend his remaining month in office doing whatever possible to avoid prison time. Simply cleaning up his mess will be his last task in office, as his ultimate goal is not to go to jail. He will pardon himself and not be prosecuted.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-will-trump-do-if-he-loses-the-election/what-will-trump-do-if-he-loses-the-election-2/', '2020-10-21T12:00:00Z', '2020-10-21T12:00:00Z'),
  ('l6640', 'what-will-trump-do-if-he-loses-the-election', 'starseed', 'name', null, array['The final two months of 2020 are likely to be the climax of a historic year. After a global pandemic, economic collapse, climate catastrophe and historic social unrest, the USA is poised for an all-out civil war in November and December. The president has made clear that he has no plans of leaving the White House and will do all in his power to keep the presidency. He has an armed militia cult following already trying to intimidate voters and speaking about starting a war if Trump loses in November. The Democratic side can only hope that the military, which is supposed to be unaffiliated, will step up and protect democracy. However, there is likely to be bloodshed at the feet of Trump who will be commanding, via twitter, from the protection of his bedroom.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-will-trump-do-if-he-loses-the-election/what-will-trump-do-if-he-loses-the-election/', '2020-10-21T12:00:00Z', '2020-10-21T12:00:00Z'),
  ('l6637', 'what-will-trump-do-if-he-loses-the-election', 'gaia', 'name', null, array['Trump’s world is predictable, transparent and simple. Even his erratic behavior always follows the same overarching trends. He lies so often that we can predict with good likelihood that the truth is the opposite of what he says. He is a clinical narcissist who always (and predictably) puts his own interests first. He is also very clearly depressed, and derives all self-worth from perceived power. So given these factors, here is my prediction:', 'Trump will lose decisively in November, and after an attempt at fighting it, he will realize that his presidency is over. He will then pardon all his henchmen and attempt to pardon himself. He will leave office after what he calls a rigged election that he will spin as having actually won. Jail time would be the only true loss for Trump, and he will do all he can not to go to prison – even if that means playing dirty. His goal will be to use his cult following to start a show on FOX where his political rants can be unhinged. Ultimately, that will be the only way he can keep some of the power that he will so desperately cling to. If he does get sentenced, he will commit suicide. Though if you ask me, watching Trump rot in prison, with a scruffy beard and bald head, would be the greatest poetic justice in the history of humankind.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-will-trump-do-if-he-loses-the-election/qotw1018/', '2020-10-21T12:00:00Z', '2020-10-21T12:00:00Z'),
  ('l6670', 'how-will-history-describe-the-year-2020', 'big-dave', 'name', null, array['Many imaginary switches have been flicked in 2020. Some good, some bad – to put it lightly. The Earth has spoken through a deadly virus, vicious wildfires and storm surges, that human-induced climate change is an existential threat to our own species as well as almost every other species on this planet. Never has there been a year so packed with messages as to this point. Whether we heed the warnings or not will determine our fate, however the year 2020 is a pivoting point for the issue of climate change.', 'Social and racial inequality was another key point of the year 2020. We will look back at this year as a year of extremes. On one extreme, racial injustice was brought to the light in a way previously unimaginable. BLM is now common knowledge among even moderately political folks. On the flip side, alt-right groups have been given a voice, and thus highlighted the previously submerged racism that is still rampant in our society. Overall, the issue of race and equality hit a peak in the public eye in 2020. When we look back, we will either see a society that moved towards equality or away from it after this extreme spark of awareness.', 'Perhaps more than anything that will be remembered in the year 2020 is the psychological dimension. The year begun with a president who had destroyed the notion of ‘truth’ and already lost the trust of most of the nation. This foundation was then built upon by an unprecedented deadly virus. Without good leadership, people were left with financial stress, fear of their / their loved ones’ safety, and an unknown future. The trauma that was collectively experienced in our nation and the world in the year 2020 is likely some of the most severe in history. The economic strain on the middle and lower class, not to mention the long-term effects yet to be endured, are and will be debilitating for years to come. Young people have to attend school online during their formative years. People of all ages have lost physical touch, platonic intimacy, and social gatherings – all of which are instinctual for humans. Racial injustice ensued through it all, leaving the black community ungrounded and further disenfranchised. The president has threatened to ignore the election results, the republicans are blatantly cheating the election, and the right-wing militias are armed guarding polling stations. All this is under the umbrella of climate change, the most existential threat in our species’ history, with record-breaking events at every turn. The trauma is strong in the air, and we are breathing it in every day. The year 2020 will be remembered as the birth of modern collective trauma – an energetic wave that will flow through our national and global society indefinitely.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/how-will-history-describe-the-year-2020/qotw1025-3/', '2020-10-26T12:00:00Z', '2020-10-26T12:00:00Z'),
  ('l6664', 'how-will-history-describe-the-year-2020', 'ruby', 'name', null, array['More than anything, 2020 will be remembered as the year that ‘truth’ died. The pandemic, the social unrest, and the exacerbating climate are all sub-categories under the president and his wave of cult-like supporters in this country. With everything that has happened, the overarching theme is that ‘truth’ has been dampened and softened. It is no longer sacred.', 'Trump has normalized certain tactics to simply discredit truth, on no basis whatsoever, except for pure opinion. With enough support, this tactic works. There is no third-party “god” up there to pick who and what is right, so we are left talking to a wall and trying to move forward against a current of constant backlash. As previous dictators have done, Trump has illuminated a mechanical way of subduing truth that is now accessible to anyone who chooses to use it. This is the new normal, and we are well en route to the end of humankind as we know it.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/how-will-history-describe-the-year-2020/qotw1025/', '2020-10-26T12:00:00Z', '2020-10-26T12:00:00Z'),
  ('l6693', 'predict-the-outcome-of-the-2020-election', 'joleen-s', 'name', null, array['Trump leads briefly during the vote counting period, and claims victory. He goes on to lose in both the popular vote and electoral. He tries his options via the Supreme Court, but realizes he doesn’t have any. He resolves to try and motivate his base to act by claiming that the voting was rigged. There is chaos in the streets for days, with a sub-par effort by the police. However, once the initial wave subsides, Trump and his supporters resign to their fate.', 'On the congressional level, the House will remain under democratic control, and after a fierce battle in the senate, it will remain under republican majority. A seat or two will be flipped, but it will not be enough to flip the whole senate. Thus, the next four years will be partially muted by the congressional stalemate that plagued Obama’s presidency too.', 'Trump will do whatever possible, during his lame duck session, to spite the democrats. He will use his Supreme Court majority to pass a number of bills intended solely for the purpose of causing road-bumps for the next administration and the majority of people in this country.', 'So there you have it – on the eve of the most intense election in modern American history and perhaps the history of human civilization, we wait anxiously to find out if America is too stupid to continue as a nation.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/predict-the-outcome-of-the-2020-election/qotw1102-3/', '2020-11-03T12:00:00Z', '2020-11-03T12:00:00Z'),
  ('l6690', 'predict-the-outcome-of-the-2020-election', 'david-g', 'name', null, array['The presidential election is just two days away and the stock market has locked-in its prediction, according to one indicator. The S&P 500 (SPX) fell 0.04% between July 31 and October 31. That means the market forecasts — by a hair — that Joe Biden will win, according to CFRA Research’s Presidential Predictor.The stock market has a fairly reliable track record: Since World War II, when the S&P 500 fell in the three months leading up to the November vote during a presidential election year, the incumbent president or party of the outgoing president has lost the election 88% of the time.', 'Similarly, when the S&P 500 rises during that period, the incumbent or party of the outgoing president has won 82% of the time.The stock market had been predicting a Trump victory until Friday, when the S&P 500 tumbled 1.2%. That was just enough to send stocks negative over the past three months, giving the razor-thin edge to Biden. “This year, the Predictor closed ever so slightly in the red during this three-month period, implying, but not guaranteeing, that Biden will emerge victorious,” said Sam Stoval, CFRA’s chief investment strategist.', 'Betting on a blue wave', 'The Presidential Predictor matches Wall Street’s forecasts. Goldman Sachs analysts predict a “blue wave,” in which Democrats will retake the White House and Senate and maintain control of the House of Representatives. Goldman believes that could be a positive outcome for markets.”Such a blue wave would likely prompt us to upgrade our forecasts,” Goldman Sachs chief economist Jan Hatzius wrote in a report last month.Goldman Sachs (GS) wrote that a blue wave would “sharply raise the probability” of a fiscal stimulus package of at least $2 trillion shortly after the January 20 inauguration. The firm also cited Biden’s longer-term spending plans on infrastructure, climate, health care and education.Taken together, this spending “would at least match the likely longer-term tax increases on corporations and upper-income earnings,” Goldman Sachs wrote.Similarly, JPMorgan strategists led by Dubravko Lakos-Bujas noted in July: “The consensus view is that a Democrat victory in November will be a negative for equities. However, we see this outcome as neutral to slightly positive.”President Donald Trump has repeatedly predicted Democrats would decimate the American economy, and the stock market would crumble if they win in November.But Moody’s Analytics found that Biden’s economic proposals, if enacted, would create 7.4 million more jobs than would Trump’s. The economy would return to full employment in the second half of 2022, nearly two years earlier than under Trump’s plan, Moody’s said.A survey of CEOs conducted by the Yale School of Management in late September found that 77% of participants would vote for Biden. More than 60% predicted he would win. However a UBS survey of 500 business owners and 1,000 investors conducted in mid-October found that 55% of business owners wanted Trump to win, while 51% of investors were backing Biden.', 'Predicting the outcome', 'CNN polling shows Biden with a sizable head-to-head nationwide lead as of October 28, and within striking distance of the 270 electoral votes needed to claim victory.No incumbent has ever won a second term when there has been a recession in the two years leading up to the election, according to data from RiverFront Investment Group.The CFRA Presidential Predictor’s only incorrect forecast when the market fell in the three months leading up to an election was in 1956, when incumbent President Dwight Eisenhower defeated Adlai Stevenson despite a 7.7% stock market decline during the Suez Crisis and the Hungarian Uprising.It’s not clear what, if anything, that outlier could mean for Trump. The market is down over the past three months in large part because of a surge in coronavirus cases. Trump’s handling of the pandemic is largely unpopular, although some could also view the wave of Covid-19 infections as out of his control. Trump still scores relatively high among voters for his economic record despite the recession.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/predict-the-outcome-of-the-2020-election/qotw1102-2/', '2020-11-03T12:00:00Z', '2020-11-03T12:00:00Z'),
  ('l6686', 'predict-the-outcome-of-the-2020-election', 'neri-z', 'name', null, array['In most countries, predicting election outcomes is the job of pollsters. In Israel, a newspaper closely aligned with Prime Minister Benjamin Netanyahu chose to consult a different cohort on the question of Donald Trump versus Joe Biden: astrologists, numerologists, and palm readers. Their unanimous projection was not exactly a surprise given Netanyahu’s close ties to Trump: The U.S. president will win a second term, according to the mystics, though only after a prolonged fight.', '“Trump will get reelected, but it won’t be via knockout but on points,” one of them divined in Israel Hayom, the country’s highest-circulation daily. The newspaper is owned by Republican megadonor Sheldon Adelson and serves largely as a mouthpiece for Netanyahu.', '“The Democrats won’t respect the outcome, and Joe Biden will steal the presidency,” leading to a crisis in the United States, the astrologer added.', 'The election is dominating headlines in all the Israeli media, alongside news of the gradual easing of COVID-19 lockdown restrictions. In a country often consumed by its own turbulent politics, the American vote has eclipsed just about everything else.', 'For observers of the relationship between Trump and Netanyahu over the past four years, the fixation shouldn’t come as a huge surprise. The U.S. president has given Netanyahu huge political gifts at critical moments, helped Israel forge ties with Arab countries, and crushed Palestinian hopes for viable statehood.', 'Some 63 percent of Israelis prefer a Trump victory, seeing it as better serving Israeli interests, according to a poll released on Monday by the Israel Democracy Institute; only 17 percent said the same of a Biden win.', 'The coverage in Israel has become so granular that Amit Segal, a reporter for Channel 12 news, scolded his colleagues on Twitter for wasting their time on issues like “which polling station is more accurate in Pennsylvania.”', '“Who cares what you think?” he said. “You’re in Israel.”', 'The soothsayers of Israel Hayom predicted it would take days or weeks for the election results to become clear in the United States—echoing the projections of more temporal forecasters. They also offered predictions about politics in Israel—where voters might be called on to cast their ballots once again in the coming months.', '‘Whether or not there will be elections in Israel in the near future, Netanyahu will remain [prime minister]a and the [U.S.-Israel] alliance will continue,’ one of them predicted.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/predict-the-outcome-of-the-2020-election/qotw1102/', '2020-11-03T12:00:00Z', '2020-11-03T12:00:00Z'),
  ('l6717', 'how-is-the-usa-viewed-by-the-rest-of-the-world-right-now', 'thomas-p', 'name', null, array['I can’t speak for the whole world but I think I can comment reasonably well on behalf of the rest of the anglosphere. We (usually) don’t hate the USA, it just makes us uncomfortable and we don’t know why but it’s uncomfortable enough that we are disinclined to speak positively about America. The reason for this discomfort is essentially the Uncanny Valley effect in play. The USA, to people from Canada, Australia, New Zealand and the UK is superficially familiar, its primary language is English, we share some cultural norms but it is so far removed linguistically, socially, politically, economically and religiously from the rest of us that we can’t help but get a niggling feeling that something is wrong with it.', 'Nearly everything we enjoy in moderation in our countries seems to be either glorified to the point of holiness, rejected as tantamount to a declaration of allegiance to Satan or just rearranged so as to give us pause to realise that the USA occupies, for us, an unpleasant middle ground between not being drastically foreign enough to be seen as a point of interest and not close enough to us that we’d feel at home if we ever decided to live there.', 'A good example of this would be the difference, for me, between North Korea and Belgium. I have been to Belgium and while there is a language barrier, a different currency and some behavioural and architectural differences I don’t mind that because it’s a nice country, the people are lovely and I can’t honestly expect the whole world to learn English just for my convenience.', 'By contrast, North Korea (which I very much hope to visit someday) is drastically different politically, culturally, culinarily, historically and linguistically to anything I would encounter in any the UK or any European country. This, again, doesn’t bother me because I expect that a country half way around the world would be extremely different and I would be rather disappointed if it were not.', 'The USA however, falls into neither category, I like visiting but while I can deal with the cult of personality surrounding the Kim family I just cannot comprehend the mindset of someone who attends a megachurch. I understand religion but coming from the UK where it is a private affair conducted in small halls and centuries old chapels the screaming and chanting and fanaticism I’d expect at a North Korean military parade seems violently out of place and indeed, uncultured and tacky when associated with what I’ve always seen as a rather solemn and dignified practice.', 'There are many more examples of this but I believe the underlying theme of English speaking people’s criticisms of the USA is that they would like to understand it, but it’s idiosyncrasies make it easier for us to identify with Czechs or Belgians.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/how-is-the-usa-viewed-by-the-rest-of-the-world-right-now/qotw1115-3/', '2020-11-14T12:00:00Z', '2020-11-14T12:00:00Z'),
  ('l6714', 'how-is-the-usa-viewed-by-the-rest-of-the-world-right-now', 'david-barry', 'name', null, array['Its a young nation. It had every right to fight and gain its independence from the British Empire. It developed successfully, technologically and its citizens helped invent many great contributions to the modern world.', 'It was reluctantly drawn into two world wars and sacrificed its men in war for peace and many will say to develop its global power. The USA helped forge independence for many European nations after the Great War. The USA’s greatest time could be said to be after WW2. The Marshall plan did help Europe. The Cold War was an unfortunate event,… of course.', 'Since WW2, the USA has been the dominant power, especially after the fall of the Soviet Union. However all great powers do not remain all powerful for ever. China looks set, or already is, to be the world’s major power. The USA, needs to accept this peacefully. China, however is not so bothered with being a dominant power and just wishes to do business with the rest of the world.', 'If the USA lets go of egoistic nationalism and ideas of supremacy and chooses to work with the rest of the planet, rather than try and dominate, then the USA’s greatest period of its history may still be to come. It just won’t be the “Number One Super Power”.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/how-is-the-usa-viewed-by-the-rest-of-the-world-right-now/qotw1115-2/', '2020-11-14T12:00:00Z', '2020-11-14T12:00:00Z'),
  ('l6711', 'how-is-the-usa-viewed-by-the-rest-of-the-world-right-now', 'richard-w', 'name', null, array['Since Donald Trump took office as president, the image of the United States has suffered across many regions of the globe. As a new 13-nation Pew Research Center survey illustrates, America’s reputation has declined further over the past year among many key allies and partners. In several countries, the share of the public with a favorable view of the U.S. is as low as it has been at any point since the Center began polling on this topic nearly two decades ago.', 'For instance, just 41% in the United Kingdom express a favorable opinion of the U.S., the lowest percentage registered in any Pew Research Center survey there. In France, only 31% see the U.S. positively, matching the grim ratings from March 2003, at the height of U.S.-France tensions over the Iraq War. Germans give the U.S. particularly low marks on the survey: 26% rate the U.S. favorably, similar to the 25% in the same March 2003 poll.', 'Part of the decline over the past year is linked to how the U.S. had handled the coronavirus pandemic. Across the 13 nations surveyed, a median of just 15% say the U.S. has done a good job of dealing with the outbreak. In contrast, most say the World Health Organization (WHO) and European Union have done a good job, and in nearly all nations people give their own country positive marks for dealing with the crisis (the U.S. and UK are notable exceptions). Relatively few think China has handled the pandemic well, although it still receives considerably better reviews than the U.S. response.', 'Ratings for U.S. President Donald Trump have been low in these nations throughout his presidency, and that trend continues this year. Trump’s most negative assessment is in Belgium, where only 9% say they have confidence in the U.S. president to do the right thing in world affairs. His highest rating is in Japan; still, just one-quarter of Japanese express confidence in Trump.', 'Attitudes toward Trump have consistently been much more negative than those toward his predecessor, Barack Obama, especially in Western Europe. In the UK, Spain, France and Germany, ratings for Trump are similar to those received by George W. Bush near the end of his presidency.', 'The publics surveyed also see Trump more negatively than other world leaders. Among the six leaders included on the survey, Angela Merkel receives the highest marks: A median of 76% across the nations polled have confidence in the German chancellor. French President Emmanuel Macron also gets largely favorable reviews. Ratings for British Prime Minister Boris Johnson are roughly split. Ratings for Russian President Vladimir Putin and Chinese President Xi Jinping are overwhelmingly negative, although not as negative as those for Trump.', 'Views of Trump are more positive among Europeans who have favorable views of right-wing populist parties, though confidence is still relatively low among all groups. For instance, supporters of Spain’s Vox party are particularly likely to view Trump in a positive light: 45% are confident in his ability to handle international affairs, compared with only 7% among Spaniards who do not support Vox.', 'Ratings of America’s response to the coronavirus outbreak are also related to support for right-wing populist parties and political ideology within several countries. While ratings are low among both groups, those on the political right are more likely than those on the left to think the U.S. has done a good job handling the outbreak.', 'Thus far, the pandemic and resulting global recession have not had a major impact on perceptions about the global economic balance of power among the nations surveyed. Majorities or pluralities in these countries have named China as the world’s leading economic power in recent years, and that remains true in 2020. The exceptions are South Korea and Japan, where people see the U.S. as the world’s top economy.', 'These are among the major findings from a Pew Research Center survey conducted among 13,273 respondents in 13 countries – not including the U.S. – from June 10 to Aug. 3, 2020.', 'Racial injustice and perceptions of the United States', 'In recent months, the killing of George Floyd and other Black Americans at the hands of police has led to massive protests both in the U.S. and around the world. All countries polled in Pew Research Center’s summer 2020 Global Attitudes Survey have experienced protests in response to these events. Many demonstrations took place during or directly prior to the fielding of our survey.', 'Certainly, these events may have had an impact on how people think about the U.S. Our survey did not include questions about the protests, Floyd’s killing, the Black Lives Matter movement, police brutality or racial injustice. However, Pew Research Center has conducted some research relevant to these issues in recent years.', 'A recent Center analysis showed the extent to which the debates sparked by the killing of George Floyd have spread beyond America’s shores. The study examined legislators in four predominantly English-speaking countries and found that many had tweeted about Floyd or used the phrase “Black lives matter” or the #BlackLivesMatter hashtag. This includes roughly six-in-ten British members of Parliament (59%), 44% of Canadian representatives and about a quarter (26%) of Australian lawmakers who tweeted during the study period. And 14% of legislators tweeted about this subject or used the phrase or hashtag in New Zealand, a country not included in the current survey.', 'Concerns about racial injustice fit into a broader pattern of decline in the belief that the U.S. government respects the personal freedoms of its people. We first saw a decrease on this measure between 2013 and 2014, as news broke about Edward Snowden and National Security Agency surveillance around the world. We saw further declines in 2015 following protests in Ferguson, Missouri, in response to the police killing of Michael Brown in August 2014. And we observed continuing erosion on this measure through 2018, the last time the question was asked.', 'Country spotlights: Canada, Germany, South Korea', 'Findings from Canada, Germany and South Korea illustrate key patterns in how foreign publics view the U.S. and its president.', 'Canada: Favorable opinion of U.S. and confidence in its president at all-time low', 'Like all countries surveyed this year, Canada’s favorable rating of the U.S. dropped sharply in 2017 as confidence in the U.S. president plummeted. In the more than three years since Trump first took office, views have slowly shifted, but 2020 sees the lowest ratings for the U.S. in Canada since Pew Research Center began polling there almost two decades ago.', 'Only 35% of Canadians have a favorable view of their southern neighbor, and 20% trust Trump to do what is right regarding world affairs.', 'Germany: Deeply negative views of the U.S.', 'Germans give the U.S. some of its worst ratings in the survey. Only 26% have a positive view of America, while just 10% have confidence in Trump when it comes to his handling of world affairs. These opinions are in stark contrast to the very favorable assessments Germans had during Barack Obama’s presidency, but roughly on par with views at the end of George W. Bush’s tenure.', 'Across the European countries surveyed, support for right-wing populist parties is related to ratings of the U.S. In Germany, people who have a favorable view of the right-wing Alternative for Germany (AfD) are much more likely than those with an unfavorable view of the party to have a positive opinion of the U.S. (43% among party supporters vs. 22%) or to trust Trump’s approach to international affairs (34% vs. 5%). They are also more likely to believe that the U.S. has done a good job in response to the coronavirus outbreak (25% vs. 6%).', 'South Korea: A sharp drop in Trump confidence', 'South Korea has seen a steep decline in favorable views of the U.S. since last year, but it is the only country surveyed where a majority still holds a positive opinion. At the same time, trust in the U.S. president has dropped substantially.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/how-is-the-usa-viewed-by-the-rest-of-the-world-right-now/qotw1115/', '2020-11-14T12:00:00Z', '2020-11-14T12:00:00Z'),
  ('l6732', 'if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-y', 'the-kid', 'name', null, array['Having researched this topic previously, I know that the average person will come in contact with between 800,000 and 1,000,000 people over the course of their life. Some of these people will pass as the cashier at the hardware store, and some will be as close as family or lovers. However, all these people will cross paths with us at some point in our lives, and some part of ourselves will be exchanged with some part of each of these people. Thus, I imagine an auditorium full of people, ready to hear a pithy, yet profound message – my deepest offering, deepest aspiration, for each of these beings. Having said that, here is my speech:', '‘May the light that is within me, though often skewed by my own afflictions, reach you in some way. And may the corresponding aspiration – for your deepest wellbeing, for your path out of suffering, and for your own journey to truth – be realized in this lifetime.’', 'This is all. May all beings have happiness and the cause of happiness. May all beings be free from suffering and the cause of suffering. May they never part from happiness that is free from suffering. May they abide in equanimity – free from attachment and aversion.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-you-say/if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-you-say/', '2020-11-22T12:00:00Z', '2020-11-22T12:00:00Z'),
  ('l6736', 'if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-y', 'big-dave', 'name', null, array['I have sat thinking about this question for quite some time, and have gone on a journey choosing, then un-choosing, the words to include in this speech and the message behind them. I concluded that it’s quite simple – rather than trying to preach something (which is outside of my experience and thus out of alignment with my day-to-day self), I would just approach it from the most authentic place possible.', 'I would say, ‘Thank you for offering your presence to me in this inconceivably precious life that we are both living. I may or may not ever take the curriculum you have offered me, and you may or may not ever take the curriculum I have offered you. But, like a spiders web, our overlap is essential to the whole cosmos. We have forever woven a thread through the fabric of history and thus, eternity. So for that, thank you. It’s an inconceivable blessing to have shared this plane with you.''']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-you-say/if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-you-say-3/', '2020-11-23T12:00:00Z', '2020-11-23T12:00:00Z'),
  ('l6734', 'if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-y', 'gaia', 'name', null, array['Words can never do justice to the essence of this question. But here goes:', '“Those of you who, like myself, wander endlessly through the ocean of delusion – I wish for you to see through the veil and choose faith over skepticism. I wish for you to trust the light that shines brightest for you, and journey down that path – the path of your deepest truth. The path that, once you begin to walk, you realize that there is no other path. I wish for you to find this path, walk this path, and I wish for you to enjoy the journey.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-you-say/if-you-were-to-give-a-speech-to-everyone-you-will-meet-in-your-life-what-would-you-say-2/', '2020-11-23T12:00:00Z', '2020-11-23T12:00:00Z'),
  ('l6763', 'what-is-the-most-dangerous-addiction-in-our-society', 'the-kid', 'name', null, array['Technology? Drugs? Money? Materials? Worldly appearance? Power? Feeling good?', 'These are all certainly monstrous addictions plaguing our societies today. But is there a deeper level to each of them?', 'I believe, yes. There is an umbrella covering each of these facets of our societal addictions…. and that umbrella is an addiction to… SUFFERING. Hear me out:', 'I suffered today because a girl from a dating app didn’t text me after saying she would. I suffered for hours, and still feel a twinge of suffering – almost a full day later. Never mind the million things to be inexplicably grateful for – I would rather choose to focus on suffering. But why?????', 'Since each of our infancies, we have been cultivating an addiction to suffering. Why? Because it is easy. It is familiar. It is constant. It is predictable. It is not ‘suffering’ inherently, however. Ultimately, what we are cultivating from infancy is a delusional sense of self that exists ‘separately’ from the world outside our bodies.', 'This notion is a complete confabulation, yet it gets drilled into our identity. Now, what happens is that this fundamentally mistaken view of the world naturally branches off into every facet of our lives. We feel separate from the world, and thus, we act selfishly. We do so in order to protect ourselves from perceived ‘threats’. There is an underlying ‘dis-ease’, anxiety, and disequilibrium within each of us – the voice of the ‘true self’ speaking through the facade, saying “Look deeper! Break free!”', 'We must decipher between “liking suffering” and “choosing suffering because it is familiar.” For the vast majority of us, the case is the latter. We choose suffering over and over again – why? Because it is the most familiar thing in the world to us. We know it back and front, head to toe.', 'When we attempt to solve any other addiction, I believe we are only putting a band-aid on a deeper wound. We are simply doomed to liberate ourselves completely until we liberate ourselves from our primary addiction to suffering.', 'I could go on forever talking about this – but to conclude: Everyone has the ability to break free from the chains of suffering. It is simply the effect of a delusional view of reality. The moment we see things for how they are, our suffering will cease. When we habituate this new view, the suffering will never see the light of day. It really is that simple.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-most-dangerous-addiction-in-our-society/qotw1129-4/', '2020-11-30T12:00:00Z', '2020-11-30T12:00:00Z'),
  ('l6760', 'what-is-the-most-dangerous-addiction-in-our-society', 'crystal-j', 'name', null, array['I don’t know about the whole world…but in the USA, I would have to say opioid addiction. We are having a crisis here with overdoses at an all time high.', 'Pharmaceutical companies put out large ad campaigns in the 90’s advertising supposedly “safe” opioid medications, with little chance of addiction, for those plagued with chronic pain. Physicians started prescribing these medications in record numbers.', 'Later, it was found that the pharmaceutical companies had essentially lied, or misrepresented, the actual risk that comes with these medicines. Lawsuits were levied against them and they were fined monies that were a drop in the bucket compared to the profits they made off of these drugs.', 'The damage was done. Large numbers of people were addicted.', 'Years later when the problem became apparent, opioid prescribing became highly monitored and restricted and those addicted found other sources: usually heroin, which is cheaper and more powerful.', 'It gets worse.', 'Heroin requires large amounts of the poppy plant for production so dealers found another synthetic opioid-fentanyl-which can be produced in a lab. Fentanyl is MUCH more powerful and dealers would mix it into the heroin, or just simply sell fentanyl outright.', 'That is when overdoses shot up dramatically.', 'Yes, I would have to say opioid addiction is currently the most dangerous addiction, at least in the USA.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-most-dangerous-addiction-in-our-society/qotw1129-2/', '2020-11-30T12:00:00Z', '2020-11-30T12:00:00Z'),
  ('l6758', 'what-is-the-most-dangerous-addiction-in-our-society', 'doug-r', 'name', null, array['Wow what an amazing topic. I can go in so many different directions with this topic but I have lived through a cocaine addiction and a heroin addiction and I honestly believe the most dangerous addiction is to: MONEY,POWER, & GREED. This is very much to the detriment of our children. Children grow up in daycares while both parents slave away to have bigger houses and nicer cars.', '• Society’s idea of a “successful person” consists of bragging rights regarding which college we attend, what we study in college, the type of car we drive, wat we look like, what our significant other looks like, etc.. ..We make as much money as we can just to be able to buy status symbols A.K.A. useless objects such as Boats, Brand Name Clothes, Jewelry, Furniture etc. Just to impress the other people in their lives. Furthermore, we want to brag about our kids’ accomplishes in academics sports. The desire to prove the extent of our successes drives us to focus on the superficial aspects of life.', 'I believe that people are becoming more isolated, more indifferent, and more entitled, due to the content of music and movies, combined with the stressors of society and becoming overwhelmed.', 'This addiction has caused our country to want to remove God from classrooms classrooms and even courtrooms. The more we refuse tobelieve in God the more We Believe that we become our OWN GODS.', 'This fixation on physical appearance is also very degrading to society. Social media making has hijacked young girls’ minds making them want to look like Kim Kardashian, who has had so many plastic surgeries, that level of beauty is unattainable.', 'As society loses touch with the importance of personal relationships due to the breakdown of the family unit, as well as the advent of the internet. social media, and video games. How can the next generation have genuinely fulfilling interpersonal relations with other people when they are raised by televisions, video games, and social media?', 'We buy a $200 pair of jeans while we know damn well there are millions of children starving in Africa. We as a society find it acceptable to ignore our moral consciences and remain indifferent to disparity and human suffering.', 'This world today teaches us that life all about getting what we want and doing what feels good. An entire generation seems to be dying off from drug addiction because the pressure gets so overwelming. They are taught concepts contrary to what the human conscience feels is good and just. They have so much to prove and just want love and approval but end up depressed if they just can’t pull it off. They have become terrified of admitting failure and haven’t been taught proper coping mechanisms to deal with failure in a healthy way, so they resort to self medicating while searching for approval and companionship with the hoards of other people feeling the same way.', 'Basically, we as a society have become so greedy, disconnected, and so self-centered I fear it is too late to correct the damage we have done.', 'This is not the way society should be, but this is the way it has become… WHY? Humans used to live in tribes and forage for food, but This addiction to MONEY, POWER and GREED is so dangerous because everybody agrees with it and there are almost no memories of a different way of life.“']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-most-dangerous-addiction-in-our-society/qotw1129-3/', '2020-11-30T12:00:00Z', '2020-11-30T12:00:00Z'),
  ('l6755', 'what-is-the-most-dangerous-addiction-in-our-society', 'david-s', 'name', null, array['Each community has it’s own norms, standards, stigmas and levels of what is acceptable and what is not, so this list of the top 10 addictions in modern society is in general and changes from country to country.', '1. Coffee', 'Coffee is an addictive substance.', 'It is widely used in society and therefore it’s generally acceptable which can open the door to overuse. Research indicates that drinking too much caffeine can cause restlessness, anxiety, muscle tremors, insomnia and irritability.', 'The safe zone is not more than 5 cups a day or 600 milligrams.', '2. Tobacco and Nicotine', 'Despite the increasing awareness of the dangers of smoking tobacco, it is still the leading contributor to causing health damage worldwide. An incredible 1.3 billion deaths are connected to tobacco annually.', 'The World Heath Organisation reported that smoking causes 90% of the lung cancers in men and 70% of lung cancer in woman and contributes to almost 80% of the cases of respiratory diseases and 22% of cardiovascular disease.', 'Nicotine is the addictive substance in tobacco that keeps people smoking and the tar and toxic gases from burning tobacco cause most of the damage. The safe zone is zero amounts of tobacco or smoking is advised.', '3. Alcohol', 'If alcohol was invented in modern times it most certainly would be made illegal in modern society.', 'Although alcohol has been grandfathered into or contemporary norms it is in fact as addictive and deadly as most illicit drugs. It is scientifically linked to 60 types of diseases including multiple cancers, epilepsy, and contributes highly to statistics on murder and motor vehicle accidents. Alcohol use is increasing worldwide and is abused in societies that permit it.', 'The safe zone is just 14 units of alcohol per week and that should be spread out over 7 days.', '4. Sex addiction', 'In modern society, new medias and the internet have developed an increase in sex addiction.', 'Just like the abuse of other substances or practices, sex addicts use it to escape from reality, relieve anxiety or to fulfil compulsions. It is estimated that 8% of men and 3% of women are effected by sex or relationship addiction. For many, sex becomes a compulsive behaviour rather than an expression of love.', 'It can be connected to low self-esteem and addicts develop unhealthy dependencies on hollow sexual encounters such as one-night-stands or a related practice such as pornography addiction.', '5. Illegal and prescription drugs', 'Legal opiates like OxyContin are particularly relevant at the moment in the U.S. and a good example of how addictive and dangerous prescription medicine can be.', 'The problem is that doctors prescribe appropriate drugs in good faith but there’s not enough education or support for those who need to stop or when they should stop. In addition, some prescription drugs are highly addictive and it has created an opioid drug abuse epidemic in the U.S. for many people who just need painkillers.', 'There is also the additional hazard of younger people stealing and experimenting with drugs they can find at home. The safe zone should be exactly what is prescribed in the short term.', 'Illegal drugs are of course not good for you. Drugs such as cocaine, heroin, methamphetamines etc., are bought on the black market, which is unregulated, unethical and highly dangerous. Taking illegal drugs is extremely dangerous as the buyer will not know where the drugs were made, what is in the drugs and what will happen after they have been consumed.', 'The United Nations estimates that 185 million people worldwide were consuming illegal drugs in the late 1990’s. The safe zone is 0 in all cases of illegal drugs.', '6. Gambling', 'While only 1% to 2% of adults develop problems with gambling it still continues to be a significant number of the population.', 'Compulsive gamblers tend to remember the highs of the wins and block out all the times they lose.', 'The excitement of the next win distorts their reality and the level of risk they are taking with their money and possessions. 80% of adults have gambled at least once in the past year and although most people have a fun and healthy relationship with it, the safe zone for gambling is if betting losses result in an inability to meet your regular financial obligations or provoke illegal activity, then steps must be taken to change the destructive gambling behaviour.', '7. The Internet and modern technology', 'A recent phenomenon has developed called Nomophobia which means “no-mobile-phone-phobia” and describes the psychological attachment some people have to their modern devices.', 'According to modern research internet addiction especially affects young people and symptoms include feelings of desperation and anxiety when separated from their phones. It has also been shown that there is a dopamine boost from overusing certain social medias which contributes to the addiction explanation.', 'An interesting experiment is to ask yourself “how much anxiety would you feel without your mobile phone”?, or to perhaps try to not use your phone for a certain amount of time.', 'The internet is quickly becoming a virtual conduit to the world and integration of technology, internet and information can become an alternate reality that is more attractive than actual reality.', 'Internet users are spending a lot more time on their computers and less time with family and friends and can show symptoms of withdrawal or discomfort when separated from computers.', '8. Video Games', 'Online gaming and virtual worlds are causing a huge upsurge in addiction to gaming.', 'As technologies develops so too does the user experience in gaming and it’s not hard to see how engaging modern gaming can be. While most people associate addiction with substances such as in the last above, doctors are now recognising addictive behaviours as well.', 'Gaming is similar to gambling in that it elevates dopamine and creates a strong psychological component to the addiction. Just like alcohol addiction is not just physical, the psychological part of the addiction creates the idea that “I can escape and feel good about my life”.', '9. Food', 'Food effects the brain chemistry in the same way that drugs do.', 'Appropriately 2% of populations have food issues, eating disorders or food addictions. Most eating disorders stem in emotional and psychological issues and because food appears to be harmless and abundant it becomes the focus for abuse. Food can offer comfort, escape and the satisfaction of compulsions or cravings for feelings that arise in daily life.', 'Like most addictions, addicts are often unaware of their damaging behaviour until something serious happens. It sometimes takes the influence of other people to start to change destructive behaviour.', '10. Work', 'While hard work is seen as a virtue to most people, overworking or “workaholism” can be a mental health condition and often a serious one.', 'Overworking can often have serious consequences on personal relationships and health yet addicts are unable to stop working, quite easily justifying it as the necessary and the responsible thing to do.', 'In addition, success from working, gaining fame and money become linked to status and self-identity. While there is nothing wrong with that by itself, the wisdom from the crowd says that a sensible work-life balance is needed to lead a consistent and happy lifestyle.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-most-dangerous-addiction-in-our-society/qotw1129/', '2020-11-30T12:00:00Z', '2020-11-30T12:00:00Z'),
  ('l6792', 'can-the-human-mind-be-trusted', 'the-kid', 'name', null, array['My friend often asks me, half sarcastically, ‘Don’t you trust your own mind? The question always receives a few chuckles. ‘Of course I trust my own mind!… Though, to be honest, no, I don’t trust my own mind at all!’ On a simple human level, the vast majority of us are puppets to the inconsistent, random, ungraspable qualities of our minds. We don’t even know what our minds are. We don’t know what our thoughts are or where they come from. For most of us, our minds are like monkeys or wild horses – and ‘we’ as beings, are completely at the whim of our crazy, chaotic minds. Even in our times of relative tranquility, peace, joy, alignment – we are caught grasping at the experience, hoping that it will not flee us. Why don’t we have the reigns of our own internal landscape? Why must we grasp as though we are servants to a greater power?', 'The reality is, as Ram Dass famously put it, ‘The thinking mind (or rational mind) is an excellent servant, but a terrible master.’ In other words, the ‘mind’ as we think of it, aka the brain, is a tool. Like the stomach, it has a very important function for our well-being. However, should it be the one with the finger on the nuclear bomb? Perhaps not. Perhaps the heart-mind, intuitive mind, or ‘Hsin’ as the Chinese would put it, is more equipped for such a job.', 'Naturally, our being is not this black and white. However, perhaps we can begin by feeling into the intelligence of our inner being and come to our own conclusions. As our society functions right now, we are a temple to the ‘rational’, ‘thinking’ mind. We idolize it. We do not recognize the magnificent tool that is the heart-mind. We do not see the short-comings of the thinking mind in being the ‘governing agent’ of the self. Naturally, each of us who idolize the ‘thinking mind’, are contributing to a macrocosmic societal model. So it is no wonder that in a society of folks who idolize the thinking mind, our society as a whole takes on that model – and vice versa.', 'However, in truth, we CAN trust the human mind. Just a different ‘mind’ than what we are used to trusting. We can trust the ‘heart-mind’ as the control center, and the ‘thinking mind’ as the lead general. This is a recipe for a compassionate, wise society.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/can-the-human-mind-be-trusted/qotw1206-3/', '2020-12-07T12:00:00Z', '2020-12-07T12:00:00Z'),
  ('l6788', 'can-the-human-mind-be-trusted', 'holly-g-kristi-h', 'name', null, array['Do you trust your brain? Researchers from Ben-Gurion University of the Negev have shown that every adult has unique brain reliability. This and other findings, published in eNeuro, the new flagship, peer-reviewed journal of the International Society of Neuroscience, offer the possibility of better identification and more accurate assessment for neurological and psychiatric disorders, including autism and attention-deficit hyperactivity disorder (ADHD).', 'Most people assume that their brain is a stable and reliable tool that works consistently. But amazingly, our brain responses are very different from those of other people. Even when we see the same object over and over again, our brains react differently each time, and the variation is surprising in size (difference is the opposite of reliability). It is even more surprising that each of us has a different level of difference/reliability that characterizes us throughout most of our adult lives.', '“Some of us have a brain that works more reliably and consistently than others, and this reliability can be measured when we record adult brain responses in the electro-encephalogram [EEG] imaging method,” explained Prof. Ilan Dinstein, head of the research team and director of the BGU’s Negev Autism Research Center. “The brain is a very stable characteristic of each person regardless of the task he or she performs; that is, whether it performs one task or another – and this characteristic, brain reliability, is very consistent over time – even when they were examined a year apart. All of the findings lead to the conclusion that, for better or worse, each of us has a brain with a certain level of reliability.”', 'Until recently, most scientists thought that brain reliability depended mainly on how attention was directed to the task being performed. Dinstein and the research team show that attentiveness is negligible compared to the identity of the person, which is the main factor. “The interesting question is whether people with greater brain reliability have different abilities than those with lower brain reliability,” added Dinstein. “For example, in previous research, we showed that people with higher brain reliability have been able to identify visual stimuli more accurately. But other animal studies have shown that too much reliability probably leads to fixation, inability to change, problems in learning new skills and adapting behavior to unfamiliar situations.', 'We plan to examine this issue in humans in other studies in our lab.”At the same time, the team used EEG records during sleep in young children to test whether low brain reliability is an early marker of autism. “We hope these findings can help in early and accurate diagnosis of the neural problem in at least some cases of autism. Autism is a very heterogeneous syndrome, but we expect that the understanding of brain activity in autism will allow us to develop and test specific treatments within the Autistic Center,” Dinstein said.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/can-the-human-mind-be-trusted/qotw1206-2/', '2020-12-07T12:00:00Z', '2020-12-07T12:00:00Z'),
  ('l6786', 'can-the-human-mind-be-trusted', 'julia-s', 'name', null, array['In this edition we tell you about a breakthrough in medical technology. A paralysed Frenchman has been able to walk again, thanks to a team of experts based in Grenoble and their revolutionary brain-controlled “exoskeleton”. Plus, we speak to Moran Cerf, a neuroscientist from Northwestern University on how and why people believe, perceive, experience and decide. But his findings come with a warning: do not trust your own brain! And in Test 24, we tell you about Guerlain’s Mindscent, a new sensory motion-led experience to help you find the perfect perfume.…”', 'https://www.france24.com/en/20191011-hacking-the-human-brain-can-we-trust-our-own-thoughts-2']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/can-the-human-mind-be-trusted/can-the-human-mind-be-trusted/', '2020-12-07T12:00:00Z', '2020-12-07T12:00:00Z'),
  ('l6783', 'can-the-human-mind-be-trusted', 'judy-s-i', 'name', null, array['The human brain is a marvelous tool. However, it was designed for a very different world than we currently live in. As a result, it retains many design flaws that do not serve us well, especially in today’s business world where new ways of thinking and ongoing innovation are essential for success.', 'Perhaps the most damaging flaw is the brain’s tendency to think it’s right. In fact, it often insists it is right even in the face of contradictory evidence. So the next time you’re absolutely, positively sure you’re right, consider these 10 reasons not to trust your brain:', '1. It jumps to conclusions.', 'The brain loves to solve problems. But as soon as a solution presents itself, the brain wants to accept it as the solution. Case closed – let’s move on to the next problem! No seeking alternative answers; no exploring possibilities. Not a good approach considering most business problems have more than one good solution and the act of exploring multiple right answers often opens doors to all sorts of success.', '2. It sees what it wants to see.', 'The brain acts as a filter, constantly screening in and screening out information. Unfortunately, it tends to screen out information that contradicts our prevailing view of the world and let in that which supports it. Ever been jilted by a romantic partner and wondered why you were the last to know? Ever been sure you had the right data and looked at the information again to find you were way off? The signs were usually there all along. Your brain just didn’t want to see them.', '3. It distorts incoming information.', 'The brain also twists and distorts incoming information so that it aligns with our attitudes, beliefs, and assumptions. If you don’t believe this, try watching Fox News or MSNBC. They make a living out of taking the same information and twisting it to suit their own agendas. Our brains do the same thing; they just don’t get to do it on national TV most days.', '4. It ignores the obvious (and then tries to justify it).', 'We know that drunk driving is dangerous, and texting behind the wheel is even worse. Yet we do them anyway. Why? Because our brain tells us we won’t get caught. Or, it assures us we won’t get in an accident. Or, we really are that important that we have to respond immediately and ignore the safety of ourselves and others. After all, it always happens to someone else, right?', 'PROMOTEDDeloitte BRANDVOICE | Paid ProgramLeading The Enlightened Workforce In The Next Normal Mitsubishi Heavy Industries BRANDVOICE | Paid ProgramWhat Does It Mean That America Is A Net Exporter of LNG? Square BRANDVOICE | Paid ProgramHow To Encourage Customer Loyalty During COVID-19', '5. It’s not designed for multitasking.', 'In today’s time-deprived, hyper-paced world, our brain wants to convince us of the virtues of multitasking. Yet, research shows again and again that multitasking increases stress, inhibits creativity, and makes us less efficient. Pause and think about that the next time you try to do five things at once!', '6. It constantly makes stuff up.', 'In the absence of information, we make stuff up. We do it all the time, and then we believe it to be true! Our brain won’t live with a void so it fills in the blanks. Most of what we make up is negative, and usually worse than the truth. Just listen to your internal dialog the next time the boss calls you into her office and you don’t know what for.', '7. It seeks to avoid threats rather than pursue opportunities.', 'Coming up with new ideas and new ways of doing things requires going out on a limb. However, in most cases the brain will choose avoidance of pain over the pleasure of some future reward. Not a good way to support innovation, which includes a certain amount of pain (failure) in order to succeed.', '8. It wants to stick with the known.', 'When stressed, the brain seeks comfort in what it is familiar with – even when it becomes obvious that the old way is no longer working. That’s why people stay in bad jobs or bad relationships. That’s why leaders hang on to projects that are clearly losing money and sucking up resources that could be better applied elsewhere. Our brains like what is familiar, not necessarily what is the best for us.', '9. It thinks everyone else sees the world the same way.', 'Logically, we know this isn’t true. But when presenting a new idea or a solution to a problem, how often do we unconsciously assume that everyone in the room sees it the same way? Then we wonder why people look at us like we’re from another planet.', '10. It has too much confidence in its own abilities.', 'Research shows that experts are only slightly more accurate than non-experts when making predictions in their fields. Moreover, when confronted with their errors, the experts almost never blamed their thinking or changed their beliefs. Instead, most attributed their mistakes to outside factors beyond their control. The next time your brain insists you’re right because “we’ve always done it that way,” you might want to step back and look at the situation from a different perspective.', 'Albert Einstein once said, “Two things are infinite, the universe and human stupidity, and I’m not sure about the universe.” I don’t think we’re stupid. But I do believe we get hoodwinked by our own brains because we don’t check in with them to see what’s really going on.', 'Call to action: Pick one of these brain flaws and start to notice when it occurs. How does it impact your decision-making?']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/can-the-human-mind-be-trusted/qotw1206/', '2020-12-07T12:00:00Z', '2020-12-07T12:00:00Z'),
  ('l6817', 'who-are-you-really', 'cnscsns', 'name', null, array['The word ‘really’ is an interesting spin on the age-old question, ‘Who are you?’ It adds a sort of comedic relief to the otherwise stressful question – at least for me. Because the great irony is that nobody knows the answer. Any answer we would give to the question ‘who are you?’ is only a placeholder. A container so as not to overstretch our boundaries of ‘self’. An attempt at solidifying the un-solidifiable. But here is my best attempt at answering the question:', '‘Who we are’ is a truth that reaches many levels. On one level, it is relatively true that we are who we typically think we are – a body, a mind, an ego, an individual being. Because that is true to us, it is ‘relatively true’. However, one level deeper, we see that we are completely interconnected with other people, the earth, and really, the whole cosmos. This is also ‘who we are’. One level deeper, we come to a space where we simply don’t know, can’t fathom, and ultimately must surrender to the unknown nature of who we are. This is beyond ‘true’ and ‘untrue’ – beyond language itself.', 'Ultimately, like carving a wooden sculpture from the trunk of a tree, who we ‘are’ is arrived at through a process of chipping away who we ain’t. We can see through the illusion that we are just our bodies. Likewise, the illusion that we are just our thoughts. Just our egos. Each of these constructs must be chipped away at in order to bear what is left behind – who we are, really.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-are-you-really/qotw1213-2/', '2020-12-13T12:00:00Z', '2020-12-13T12:00:00Z'),
  ('l6815', 'who-are-you-really', 'gylve-t', 'name', null, array['I like to think that I’m a nice guy. I think I’m friendly, enthusiastic and emotional. I think I’m really a lot more normal than people think when they meet me. This comes of the fact that I like to keep people from knowing who I really am. There’s a couple of people who think they know me, and yes they know more about me than most people ever will. But as of now, I only have two friends where I don’t feel the need to hide my true self from. One of them is on Quora. You know who you are. I keep most people out with a mix of dark and perverted humour. I guess it’s a kind of defense mechanism. But I keep people out, you never know who’s gonna use their knowledge of me to hurt me.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-are-you-really/who-are-you-really/', '2020-12-13T12:00:00Z', '2020-12-13T12:00:00Z'),
  ('l6812', 'who-are-you-really', 'mikky-ekko', 'name', null, array['So you feel entitled to a sense of control
And make decisions that you think are your own
You are a stranger here, why have you come?
Why have you come, lift me higher, let me look at the sun
Look at the sun and once I hear them clearly, sayWho, who are you really?
And where are you going?
I have nothing left to prove
‘Cause I have nothing left to lose
See me bare my teeth for you
Who, who are you?', 'Now you’re moving on and you say you’re alone
Suspicious that this string is moving your bones
We are the fire, we see how they run
See how they run, lift me higher, let me look at the sun
Look at the sun and once I hear them clearly, sayWho, who are you really?
And where are you going?
I have nothing left to prove
‘Cause I have nothing left to lose
See me bare my teeth for you
See me bare my teethWho, who are you really?
And where are you going?
I have nothing left to prove
‘Cause I have nothing left to lose
See me bare my teeth for you
Who, who are you?”', '-“Who Are You, Really?” , Ekko Mikky, Teen Wolf, 2017']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-are-you-really/qotw1213/', '2020-12-13T12:00:00Z', '2020-12-13T12:00:00Z'),
  ('l6820', 'who-are-you-really', 'big-dave', 'name', null, array['I’m one wildebeest in a herd of fifty thousand (million?). Sometimes the grazing is good, other times not. Sometimes there’s water in the river, other times not. There are the lions, of course, but some of the other beests are just as dangerous, or at least just as annoying. And some of them smell so good it’s hard even to graze near them without — you know.', 'Like every creature, I know my own physical nature — how I move through the world, how to get what I need to survive, and a sense of what it’s like to be “me.” My mind sifts those thoughts over and over, generally in sync with my immediate environment, always ready to react from instinct if the need arises.', 'But beyond just the physical, I know I’m a wildebeest. I can get my mind to think about what it might be like to be a different beest, or even a zebra — or a lion! I can graze when I feel like it, on either side of the herd or (yuck) right in the middle. I can try to mount another beest if I want to, though there could be consequences. I can be the best lion-scout in the herd if I set my mind to it, and I can even chase a lion away if I want to feel totally alive. I know I could die doing that, but I’m going to die at some point anyway.', 'When we’re on the move, I can feel the rumble of the many beests who ran before me on this same ground, and I know there will be many more running and rumbling here in seasons to follow. I am “me,” and eventually I will be nothing — “no thing” — and a moment after that the herd will have moved on without me….']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-are-you-really/qotw1213-4/', '2020-12-16T12:00:00Z', '2020-12-16T12:00:00Z'),
  ('l6936', 'who-are-you-really', 'ctinsb', 'name', null, array['I remember being in my twenties wishing I was in my forties because those people seemed to know who they were. The thought of being grounded and comfortable in my own skin was so appealing, better than most of the magazine ads I saw selling something. After having so much life experience, I can definitely say it is not age related to know who you are. Some know who they are very young, and some don’t have a clue even when they’re in their seventies. And even if you don’t know, you can still find out. It’s never too late.', 'Knowing who you are is just as important as knowing who you aren’t. Can you fall asleep at night knowing you did the best you could and didn’t hurt anyone intentionally? Are you aware that you are kind, sometimes cynical, fun, maybe pushy? Who we are is a snapshot in where we are and what is going on. But yes, there are things that are ingrained in our personality.', 'I am convinced (and I’m happy to listen to input from others) that I am loyal, silly, truthful, athletic, and annoyingly punctual. Of course I’m more complicated than that, but I feel it’s a good start.', 'I look back on those times in my twenties and feel most of that was inside me at the time, but now in my fifties it is clearer than ever.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/who-are-you-really/qotw1220-4-2/', '2021-01-04T12:00:00Z', '2021-01-04T12:00:00Z'),
  ('l6855', 'what-is-culture', 'cnscsns', 'name', null, array['Culture is a web of traditions, spirituality, religion, cuisine, dress, art, and the overall fabric of a society. It is a conglomerate of the history of the people and the land. Thus, each culture of the world today is the latest manifestation of an ongoing ebb and flow. As people migrate, as land changes, as trauma is introduced, as mindsets change, so too do cultures.', 'Culture, in a way, is what makes our planet and our species so unique. In this increasingly globalized world, preserving culture is, to many, synonymous with protecting the human race and our purpose here. Our species’ cultures symbolize our uniqueness, our creative potential, our magic. They are the food forest that make for a healthy species, and yet they are being plowed over for mono-cropping. It is absolutely important to do all we can to accept, respect, and preserve the cultures of the planet – so long as they do not cause harm to others.', 'Flipping the coin, however, we see that cultures are in constant flux – creation and destruction – and this will likely continue indefinitely – at least until our species reaches its end. Cultures will always develop, be shared, and evolve into new entities of their own. This change is natural and necessary – and inescapable in an evermore interconnected world.', 'Overall, it will come down to our species’ ability to adapt to an evermore interconnected world that will determine our success and our fitness for survival in the coming decades. Acknowledging the fundamental importance of preserving culture is central, or – like a mono-cropped field, we will be severely weakened, limited, and overall doomed. Our fitness for survival will come down, in a large part, to our respect for culture, our ability to adapt to ever-changing cultural norms, and a cultural shift towards a more ‘awake’ collective energy.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-culture/qotw1220-4/', '2020-12-20T12:00:00Z', '2020-12-20T12:00:00Z'),
  ('l6851', 'what-is-culture', 'kim-a-z', 'name', null, array['Culture is the characteristics and knowledge of a particular group of people, encompassing language, religion, cuisine, social habits, music and arts.', 'The Center for Advance Research on Language Acquisition goes a step further, defining culture as shared patterns of behaviors and interactions, cognitive constructs and understanding that are learned by socialization. Thus, it can be seen as the growth of a group identity fostered by social patterns unique to the group.', '“Culture encompasses religion, food, what we wear, how we wear it, our language, marriage, music, what we believe is right or wrong, how we sit at the table, how we greet visitors, how we behave with loved ones, and a million other things,” Cristina De Rossi, an anthropologist at Barnet and Southgate College in London, told Live Science.', 'The word “culture” derives from a French term, which in turn derives from the Latin “colere,” which means to tend to the earth and grow, or cultivation and nurture. “It shares its etymology with a number of other words related to actively fostering growth,” De Rossi said.', 'Western culture', 'The term “Western culture” has come to define the culture of European countries as well as those that have been heavily influenced by European immigration, such as the United States, according to Khan University. Western culture has its roots in the Classical Period of the Greco-Roman era and the rise of Christianity in the 14th century.', 'Other drivers of Western culture include Latin, Celtic, Germanic and Hellenic ethnic and linguistic groups. Today, the influences of Western culture can be seen in almost every country in the world.', 'Eastern culture', 'Eastern culture generally refers to the societal norms of countries in Far East Asia (including China, Japan, Vietnam, North Korea and South Korea) and the Indian subcontinent. Like the West, Eastern culture was heavily influenced by religion during its early development, but it was also heavily influenced by the growth and harvesting of rice, according to the book “Pathways to Asian Civilizations: Tracing the Origins and Spread of Rice and Rice Cultures” by Dorian Q. Fuller. In general, in Eastern culture there is less of a distinction between secular society and religious philosophy than there is in the West.', 'Latin culture', 'Many of the Spanish-speaking nations are considered part of the Latin culture, while the geographic region is widespread. Latin America is typically defined as those parts of the Central America, South America and Mexico where Spanish or Portuguese are the dominant languages. Originally, the term “Latin America” was used by French geographers to differentiate between Anglo and Romance (Latin-based) languages, according to the University of Texas. While Spain and Portugal are on the European continent, they are considered the key influencers of what is known as Latin culture, which denotes people using languages derived from Latin, also known as Romance languages.', 'Middle Eastern culture', 'The countries of the Middle East have some but not all things in common. This is not a surprise, since the area consists of approximately 20 countries, according to PBS. The Arabic language is one thing that is common throughout the region; however, the wide variety of dialect can sometimes make communication difficult. Religion is another cultural area that the countries of the Middle East have in common. The Middle East is the birthplace of Judaism, Christianity and Islam.', 'African culture', 'The continent of Africa is essential to all cultures. Human life originated on this continent and began to migrate to other areas of the world around 60,000 years ago, according to the Natural History Museum in London. Other researchers, like those from Estonian Biocentre in Tartu, believe that the first migration may have been much earlier, as early as 120,000 years ago. Researchers come to these conclusions by studying human genomes from various cultures to trace their DNA to common ancestors. Fossil records also factor into some of these theories.', 'Africa is home to a number of tribes, ethnic and social groups. One of the key features of this culture is the large number of ethnic groups throughout the 54 countries on the continent. Nigeria alone has more than 300 tribes, for example.', 'Currently, Africa is divided into two cultural groups: North Africa and Sub-Saharan Africa. This is because Northwest Africa has strong ties to Middle East, while Sub-Saharan Africa shares historical, physical and social characteristics that are very different from North Africa, according to the University of Colorado. The harsh environment has been a large factor in the development of Sub-Saharan Africa culture, as there are a number of languages, cuisines, art and musical styles that have sprung up among the far-flung populations.', 'Constant change', 'No matter what culture a people are a part of, one thing is for certain, it will change. “Culture appears to have become key in our interconnected world, which is made up of so many ethnically diverse societies, but also riddled by conflicts associated with religion, ethnicity, ethical beliefs, and, essentially, the elements which make up culture,” De Rossi said. “But culture is no longer fixed, if it ever was. It is essentially fluid and constantly in motion.” This makes it so that it is difficult to define any culture in only one way.', 'While change is inevitable, the past should also be respected and preserved. The United Nations has created a group called The United Nations Educational, Scientific and Cultural Organization (UNESCO) to identify cultural and natural heritage and to conserve and protect it. Monuments, building and sites are covered by the group’s protection, according to the international treaty, the Convention Concerning the Protection of the World Cultural and Natural Heritage. This treaty was adopted by UNESCO in 1972.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-culture/qotw1220-3/', '2020-12-20T12:00:00Z', '2020-12-20T12:00:00Z'),
  ('l6847', 'what-is-culture', 'anumit-g', 'name', null, array['Culture is a MYTH, a LIE we all are compelled to believe.', 'Homo sapiens, the so called intelligent being rules the world but a single human holds no power to exert his influence over nature, humans despite being weak, slower and less muscular paved their way to the top of the food chain all by their social skills. Thus we need association to rule the world.', 'Now the catch here is, these associations are not a child’s play. Thus we need something that could bind us together and there comes the concept of culture.', 'Hammurabi’s Code dating back to 1776 BC established a pecking order of superiors, commoners and slaves. Superiors got all the good things in life. Commoners got what was left. Slaves got a beating if they complained. And the king claimed that he was directed by the god to do so and people complied.', 'Today, in 2018 we believe in equality of all irrespective of caste, color, creed, religion or gender. Why? Because we believe God made everyone equal.', 'There’s no point of right or wrong in the above mentioned examples. All that matters is the ability of these lies to bind people.', 'Culture tends to argue that it forbids only that which is unnatural. But a truly unnatural behavior, one that goes against the laws of nature, simply cannot exist, so it would need no prohibition.', 'No culture has ever bothered to forbid men to photosynthesis or women to run faster than the speed of light.', 'So it’s a LIE we all believe and should believe in for our very existence.', 'Thank you.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-culture/qotw1220-2/', '2020-12-20T12:00:00Z', '2020-12-20T12:00:00Z'),
  ('l6844', 'what-is-culture', 'vaishali-s', 'name', null, array['Culture is a way of life. It is composed of language, religion and specific lifestyles. It can never be easy to define culture, because there exists no static definition of it. Rather, it is a continuously evolving, having dynamic entity, which characterizes the entire lifestyle of a certain group of people.', 'The term ‘culture’ has a wide usage, often lacking an understanding of the many elements it encompasses. According to UNESCO, “We speak of culture in connection with the behavior of people, the moral values, and human relations. We denote it by action, behaviour and attitudes considered useful for the interests of the society, or of a certain social group.” There are many layers associated with the word culture, and hence it is often sub-divided into categories with narrower definitions enabling identification of various elements of culture. One such classification could be material and non-material culture, the former including arts, architecture, etc., and the latter including belief systems, myths, legends, etc.', 'The etymology of the word ‘culture’ can be traced back to Roman times. It originally meant cultivation of soul or mind, and it is only after the influence of German thinkers of 18th century that it came to acquire its present meanings.', 'Cultures, or cultural values evolve continuously, as people interact with one another. There is an intermingling of values, and material ways of life, and thus culture alters itself by both processes – one when it accommodates change, and second when it resists change. Contact between societies remains the most important factor influencing culture, and over time, this contact has only increased. Today, the extent of cultural intermixing is such that cosmopolitan cities have come up at numerous places across the world, which is underlined by a common thread of cultural values despite the varied difference in the ethnicity of settlers there in.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-culture/qotw1220/', '2020-12-20T12:00:00Z', '2020-12-20T12:00:00Z'),
  ('l6892', 'imagine-you-attended-your-own-funeral-and-gave-your-own-eulogy-what-would-you-sa', 'cnscsns', 'name', null, array['If I were to die tomorrow, yet somehow speak at my funeral, I would want to speak honestly. I believe it is important to honor the truth as to how this being appeared to ME. Thus, for my funeral, I would say that I was a work in progress. I died pre-maturely in the sense that I did not yet make the turn towards adulthood, responsibility, and overall my greatest potential.', 'I was a kind, soft-spoken, open-minded person. I was a jack of all trades, with a passion for creative projects and making a dent in the system. I was an adventurous, free-spirited traveler. A good question asker and listener.', 'I was also selfish, especially when it came to my friends and family. I lived with a lot of fear – around intimacy, the future, my purpose, success and failure. I had a blatantly deluded self-image. I had a lot of unresolved darkness. I didn’t really give the people in my life the love and respect they deserved.', 'These are a few of the points I would feel are necessary to make. There are many more, but overall I think dying anytime soon would yield a less-than-adoring eulogy. I am due for a grand transformation in the near future, if I dare to imagine a positive eulogy.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw1227/qotw1227-2/', '2020-12-27T12:00:00Z', '2020-12-27T12:00:00Z'),
  ('l6886', 'imagine-you-attended-your-own-funeral-and-gave-your-own-eulogy-what-would-you-sa', 'dorothy-w', 'name', null, array['Who the fuck decided I shouldn’t wear my pink silk dress? It’s literally the only thing I wanted about my funeral. Well, not the only thing, speaking of! Why is My Chemical Romance’s Fake Your Death not playing? I mean it’s a bit boring now that I’m speaking, but then again if someone caught this on video, it could go viral, so why not. Also, who brought a bouquet with lavender? And why! I hate lavender. Should’ve brought me roses. Actually, you know what would’ve been cool? A flower crown of poppies. If I were wearing that now, the petals would fall off slowly during this little impromptu speech. I feel like that would’ve added some effect. Never mind. Right, you. Why are you here? I’ve always hated you. You freak me out.', '“Why aren’t my bjj team here? Don’t they know I’m dead? Oh, hi Jim, where the hell are the rest? No, I mean, I know why my classmates aren’t here, but why aren’t my bjj guys here? I let several of them choke me, I feel like we had a special something. Just me and then 20 guys I rolled around with a few times a week. By the way Jim, you should wear a suit more often.', '“Free bar, huh? Was that my dad or Patrick’s decision? Where’s the cake though? I thought you wanted to honour my memory, so there should be cake. Is there at least pasta somewhere?', '“Hey, what are you gonna do with my remains? Scatter me over the streets I used to walk? If you do that, please don’t burn me first. I’d like to cause just one more riot. You know what would be really cool to do with me? Me neither. Oh! You could burn me and then put me in a Coke can and keep it in your fridge. Come on, that would be funny.', '“Anyway, enjoy your boozed up cakeless party. Cause that’s totally in my spirit. Seriously guys. Whatever, I’m gonna get naked, and go take a nap in an open casket. Wake me when mcr gets back together. Ffs.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw1227/qotw1227/', '2020-12-27T12:00:00Z', '2020-12-27T12:00:00Z'),
  ('l6933', 'what-can-we-learn-from-solitude', 'chan-lee', 'name', null, array['Periods of solitude are vitally important for every human being out there – whether they identify as an introvert or extrovert. Here’s why: Our identities are conglomerates of external projections that we have internalized and confused with ‘self’. When we are around people, we naturally fall prey to our habits of accepting and becoming these projections of others… So much so, that it is quite easy to completely lose sight of the being that lies naked beneath. In solitude, this being has the conditions to emerge – intentionally or not. With solitude often comes immense discomfort – a natural reaction similar to baby skin being exposed to the cold.', 'Our often intense reaction to solitude is most significantly based in the fact that the ‘self’ that emerges in these conditions is full of shadow elements. It is a blend of traits, thoughts, and tendencies that are rejected by society, and thus rejected by ourselves. They are the darkest of the dark. Naturally, these are not pretty to look at, let alone with engage with. However, as much as we may seek to be free of them, we cannot do so without escorting them out the door.', 'As Ram Dass said,', '“If we are to be free, there is nothing we can push away.”', 'The only way to emancipate this pent up darkness is through direct contact, interest, reflection, and intentionality. We must embrace ‘what is’ truly and deeply, without judgment and prioritization. It is ALL valid – the good, the bad, and the ugly.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-can-we-learn-from-solitude/qotw-0103-3/', '2021-01-03T12:00:00Z', '2021-01-03T12:00:00Z'),
  ('l6931', 'what-can-we-learn-from-solitude', 'benjamin-e', 'name', null, array['Solitude is one of my favorite gatherings. You’re only alone if there is too much of you there. So I’ll try to leave some of myself behind.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-can-we-learn-from-solitude/what-can-we-learn-from-solitude/', '2021-01-03T12:00:00Z', '2021-01-03T12:00:00Z'),
  ('l6927', 'what-can-we-learn-from-solitude', 'kelsey-o', 'name', null, array['Since the beginning of the pandemic, Paul Fredette and Karen Karper Fredette have made some changes to their lives: Ms. Fredette stopped attending her local exercise class, and the couple whittled their interactions with their neighbors down to waves.', 'But in many ways, seclusion comes naturally to them. From a house they call Still Wood, nestled in the slope of a mountain surrounded by hundreds of acres of wild woodlands, the Fredettes live their lives “oriented towards solitude,” which is their preferred way of saying that they’re hermits: devoted to simplicity, silence and prayer. The nearest town, Hot Springs, N.C., is 18 miles away and has a population just under 600.', 'Mr. Fredette, 71, is a former Catholic priest, while Ms. Fredette, 78, spent 30 years in a monastery after high school before leaving to live as a hermit in a cabin in West Virginia. Since 1996, the couple has overseen a social network for hermits and the hermit-curious called Raven’s Bread Ministries. They provide spiritual counseling to seekers of solitude, write books on the topic, run a website and deliver a quarterly newsletter, Raven’s Bread, which includes contributions from the greater hermit community.', 'The original idea for Raven’s Bread Ministries was to validate hermits’ attraction to solitude. But this summer the Fredettes felt called to minister to a different demographic: those struggling with the isolation of the coronavirus pandemic. After noticing their average daily website hits went from around 800 pre-pandemic to up to 2,000 in August, the Fredettes began creating YouTube videos. Listening to them feels a bit like getting a very quiet pep talk from your grandparents, or watching an unusually spiritual A.S.M.R. video.', '“A lot of people are going to be in pain, and if you know there’s something you can do to alleviate some of that pain, do it,” Ms. Fredette said.', 'Some contemporary hermits say prayer and meditation can be done while simultaneously engaging in other activities, like yard work.Credit…Clark Hodgin for The New York Times', 'In addition to “affirming and supporting” hermits, the Fredettes serve as unofficial spokespeople on their behalf, dispelling the Unabomber stereotype that looms large in the public imagination. Like everything these days, hermits exist on a wide spectrum and prefer a variety of identifiers: lovers of solitude, solitaries, contemplatives. (Ms. Fredette likes to add “contemporary” as a qualifier, to make the lifestyle sound less antiquated.)', 'Although some version of the solitary exists in nearly every religious tradition, eremitism is most commonly associated with the early Christian Desert Fathers and Mothers of the third and fourth centuries. Academics have found interest in eremitical life to be tied to the strength of centralized ecclesiastical institutions at the time, as well as increasing industrialization and urbanization.', 'Today, there are hermits who have been officially professed by their respective religious institutions — in Catholicism they are called “canonical hermits” — and rogue hermits who answer to no spiritual authority. There are hermits who live in caves, like the Himalayan Hermit, who spends his summers in a mountain crevice 10,000 feet above Gangotri, India. But many more hide in plain sight, in suburbs and cities.', 'The Real Life of a Hermit', 'Hermits have never been quite as isolated as many assume: They have often attracted devotees and have always had to earn their own living, which means allowing for some contact with the outside world.AT HOME: Our best suggestions for how to live a full and cultured life during the pandemic, at home.Sign Up', 'Contemporary hermits might take jobs that require little human interaction, like cleaning houses. They try to fill what extra time they have with spiritual practice, rather than social interaction, in person or online, and make choices that support that end: They’ll meditate on their commute rather than read the news, or only answer their phone during designated hours.', 'They can live anywhere, but tend to reside in modest dwellings and avoid moving around unnecessarily. Nevertheless, a hermit should also not be confused with a recluse. The difference, Ms. Fredette said, is that hermits do not exit society because of misanthropy. “I would define a hermit or a person who chooses solitude as one who chooses solitude for spiritual reasons,” Ms. Fredette said, “and we do accent the spiritual, but it can be any form of spiritual.”', 'Despite the hermit’s religious origin, a surprising number of subscribers to Raven’s Bread describe themselves as “formerly” religious and say they don’t affiliate with a particular church or faith group.', 'The topics of the Fredettes’s videos are wide-ranging: Sometimes the couple encourages viewers to journal their worries, sometimes they mirror back feelings of despair and anger, and sometimes they relay comparable experiences from their own lives, such as when Ms. Fredette had to miss family gatherings while cloistered at the monastery.', 'ADVERTISEMENTContinue reading the main story', 'They lead mini-guided meditations and quote solitary luminaries like Thomas Merton and Julian of Norwich, a medieval mystic who lived through the Black Death and civil unrest. The Fredettes also touch upon the events of our day, like racial injustice and climate change. “We’re not separated from what’s going on around us,” Ms. Fredette said.', 'The Fredettes began creating YouTube videos to help hermits and hermit-curious people deal with isolation.Credit…Clark Hodgin for The New York Times', 'Can Anyone Embrace Solitude?', 'Hermits themselves are torn on the issue.', '“Solitude is not like protein,” said Heidi Haverkamp, a Raven’s Bread subscriber and the author of “Holy Solitude: Lenten Reflections With Saints, Hermits, Prophets, and Rebels,” who describes herself as a part-time solitary. “Some people find what I get from solitude in music or in exercise, just different ways that they access the transcendent.”', 'Several people pointed out that solitude for them is more a tool than simply a comfortable loneliness. “Solitude is a means,” said John Backman, a writer and “quasi-hermit” who affiliates with both Zen Buddhism and Christianity. “It is a means to draw closer to, immerse oneself in, that or who which is larger than we are, to immerse ourselves in Spirit, as it were.”', 'But the Fredettes and other hermits believe that anyone could benefit from incorporating some eremitic fundamentals — such as being rooted in place, practicing austerity and committing to a daily schedule that prioritizes prayer or meditation — to help them make sense of their isolation into their lives, regardless of personality type, religiosity, or life circumstances.', 'For people with little to no background in hermit spirituality, the pandemic has proved the ideal entryway. Karthik Kotturu, 27, of Gurugram, India, who described himself as spiritual but not religious, said that after an initial rocky adjustment to lockdown life, he found solace in the teachings of Zen Buddhism.', '“The pandemic made me realize how afraid I was of being alone,” he wrote in an email. Discovering the Zen idea of detaching from the world — in the words of the Tao, eliminating both “longing and aversion” — helped him to shift his perspective. “Once I started seeing what I already had, my desires to seek something from outside started decreasing.”', 'Others have found that the situation has allowed them to tap into a love of solitude that was always present but neglected because of life obligations. Hannah Sheldon-Dean, 32, a writer and editor living in Brooklyn, said her morning chores have become a slow, calming routine, and she always ends her days by listening “Harry Potter and the Sacred Text,” a podcast in which the hosts do a deep read of the Rowling series, sometimes utilizing Lectio Divina principles, a Christian style of reading which involves approaching a text in four unhurried stages: read, meditate, pray, contemplate.', '“I’ve always had ritualistic and contemplative tendencies like the ones the hermits describe, but the pandemic has just given them more space to flourish,” Ms. Sheldon-Dean said.', 'Some contemporary hermits say prayer and meditation can be done while simultaneously engaging in other activities. And all the hermits interviewed described experiencing a psychological dredging process in the early days of their solitude (they described the emotions that came up as “junk” or “sludge”) and emerging as evangelists for self-love.', '“When we’re alone, all the fears and worries and anxieties come up, because we can’t distract ourselves,” said Sister Elizabeth Wagner, a canonical hermit who lives in her own “cell” on the grounds of a communal hermitage in Central Maine. “The great way to be with ourselves, to embrace who we are, warts, bumps, lumps and all, is to breathe.”', 'Ms. Fredette said that the understanding that your own “deeper self” is always beside you is the key to transforming anxiety-ridden isolation into nurturing solitude. “Once you begin to talk to yourself, know yourself, then you realize you’re not alone.”', 'The Fredettes’ property, 18 miles from the nearest town.Credit…Clark Hodgin for The New York Times', 'Nature’s Divinity', 'The most potent grounding force of all, many hermits said, is nature. Hermitic life and environmentalism are natural bedfellows: Hermits generally travel infrequently — the term “anchorite” refers specifically to a religious solitary who takes a vow to remain in one place, though even non-anchorite hermits tend to be homebodies — and eschew rabid consumerism.', 'Awe in the face of the natural world runs like a thread through the history of eremitism, from the pastoral poems of the Yuan dynasty hermit Stonehouse right up to the work of the Charles Brandt, the Vancouver Island priest-hermit who fought tirelessly for the preservation of the streams and forests around the cabin he called Merton House.', 'Today, some hermits just walk around in a patch of grass, something Sister Rachel Denton, a canonical hermit in Sheffield, England, called “prayer walking.” She also picks up litter in the public park across the street from her home, a community service she calls her “penance.”', '“I suppose there’s a therapy in there as well,” said Sister Denton. “Your body doing the walking, doing the pacing, it’s like a mantra.”', 'Alternatively, some hermits make friends with nature, like the Fredettes have.', '“We have a rock, a huge rock, that’s sticking out of the mountains,” Ms. Fredette said. “Her name is Petra. And we have a path that leads right out to Petra. And when things are difficult I go out and I lean on Petra, and I say, ‘Give me some guidance.’']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-can-we-learn-from-solitude/qotw0103-2/', '2021-01-03T12:00:00Z', '2021-01-03T12:00:00Z'),
  ('l6923', 'what-can-we-learn-from-solitude', 'becca-c', 'name', null, array['Last week, I did something a bit unconventional. The Dutch call it uitwaaien, and it means to take a break in the countryside to clear one’s head or, literally, “to walk in the wind.”', 'I didn’t realize this was what I was doing. I just knew that life was filling me up faster than I could consume it. I was becoming forgetful – and anxious – and sleepless – and maybe just a little bit confused. And all I wanted, more than anything, was to get away. Into nature. Into the mountains beneath the tall, ancient redwood trees. By the wild parts of the ocean where the waves crash fiercely against the weathered rocks. I was craving solitude.', 'So my social-media obsessed, internet employed self decided to take this message my body was telling me very seriously and got outta town.', 'And it was the best decision I could have made – for my brain, for my heart, for my body. Nature and solitude heals, and I knew I had to share this with you. I believe in sharing these experiences with our sisters (and brothers), because that’s where the true connection and transformation occurs. When we are of service to each other – whether it’s by sharing your grandmother’s recipe for chicken noodle soup or the way you coped with overwhelm in life. We all have the tools, collectively, to help each other live healthier, happier lives. And I want to be a part of spreading that.', 'Things I Learned in Solitude', 'A Letter to Myself', '• Don’t follow other people’s blueprints. It’s soooo tempting in this world, but blazing your own path just feels so much better. Remember this when you feel like giving up.', '• 9 hours of sleep is what your body wants, that’s just real.', '• Being alone is hard, but worth it when you can finally listen to what you really want.', '• Sunlight heals, not darkness.', '• The sound of the ocean is also unexpected medicine.', '• You are inspired when you put yourself in a beautiful environment. Creativity can’t flow in a colorless prison cell.', '• Start the morning right — green drink, deep breaths, clear heart –it sets the tone for the rest of your day', '• Give yourself room to settle in. It can’t be perfect all the time.', '• Don’t be precious.', '• Clarity comes. Believe.', '• Miracles happen in the most unexpected places', '• Food is less of a comfort when you are more aware and loving of yourself. (Proof: downing a bag of kale chips in less than 60 seconds when you thought you lost your phone)', '• Practicing self-care makes your body very happy. Stretch. Walk. Shower outside while looking at the ocean. Moisturize your feet before bed. Massage your desk chair-weakened, sore leg muscles. Take extra long to enjoy your nighttime skincare routine.', '• Be grateful for all the little things like the google maps app, the cottage cat that slept with you while it poured rain outside, supportive friends (new and old), and strong, artistic, & fierce women.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-can-we-learn-from-solitude/qotw0103/', '2021-01-03T12:00:00Z', '2021-01-03T12:00:00Z'),
  ('l6960', 'what-is-loneliness', 'nick-s', 'name', null, array['Loneliness is the inability to connect with one’s environment. It may come in the package of being alone in the desert, or it may come in the midst of a big city. From my experience, the most profound loneliness arises from a feeling of claustrophobia – from inside my bag of skin to the outside world. It becomes a palpable discomfort that pulsates through the physical body. It becomes a debilitating, prison-like experience that is difficult to escape. I would best describe it, like a rotting fruit, as the rotting of our deepest yearning (for connection) within our own bodies and minds. We usually rely on other people, certain physical environments, and other habits, to fill our void spaces and project our values. However, when these are stripped away from us, often what is left is that void, without access to an easy filler. The fear that arises from here pulsates through us and zaps the feeling of control we usually have. This is loneliness, in my experience.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-loneliness/what-is-loneliness-2/', '2021-01-11T12:00:00Z', '2021-01-11T12:00:00Z'),
  ('l6958', 'what-is-loneliness', 'gaia', 'name', null, array['[et_pb_section admin_label=”section”]
 [et_pb_row admin_label=”row”]
 [et_pb_column type=”4_4″][et_pb_text admin_label=”Text”]
“At it’s core, loneliness is the feeling of ostracization from one’s environment. The sensation itself, however, can be wrapped in a number of different molds – most commonly the feeling of being ‘alone’, estranged from the external environment in which you currently exist. Loneliness, however, is an emotion, and is rooted in one’s INTERNAL world. It is, thus, a deeply subjective experience. Take this example: Solitary confinement is considered to be the most extreme punishment, given to criminals of the worst offenses. Yet, solitary retreat is voluntarily undergone by spiritual seekers around the world. Loneliness is, thus, deeply contextual and must be examined deeply.”', '[/et_pb_text][/et_pb_column]
 [/et_pb_row]
 [/et_pb_section]']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-loneliness/what-is-loneliness/', '2021-01-11T12:00:00Z', '2021-01-11T12:00:00Z'),
  ('l6955', 'what-is-loneliness', 'shai-s', 'name', null, array['Loneliness is that negative feeling that arises when our social needs are unmet by the quantity and quality of our current social relationships. As social beings, we rely on safe, secure social surroundings to survive and thrive. When we begin to feel lonely, we experience heightened feelings of vulnerability, which can take a toll on both our bodies and our minds.', 'Loneliness is common, affecting around 1 in 3 adults. With COVID-19 shutdowns driving people into their homes and increasing physical isolation, loneliness is a feeling that many of us might be feeling right now.', 'According to a recent study of 5070 participants conducted by Associate Professor Jilly Newby at the Black Dog Institute, over 50% of people reported feeling lonely during the pandemic.', 'For some it may be temporary, and for others it may be more long term. The subjective nature of loneliness means that people can live relatively solitary lives and not feel lonely while others may lead a seemingly rich social life and feel quite the opposite. Loneliness is not a sign of vulnerability, fragility, or weakness, nor does it occur only in people who are physically isolated or who are elderly. We can have many people around us and still feel lonely.', 'What puts people at risk of experiencing loneliness?', 'Research has found loneliness to be a modestly heritable[i] trait which affects how distressed social disconnection makes you feel – but environment tends to play a larger role. Social isolation, living alone, the recent death of a loved one and health issues are all situations that may result in a person experiencing loneliness.', 'Rachel Cohen, a clinical psychologist at the Black Dog Institute, says that the loneliness we might be experiencing now can be reduced with the help of social media, but it’s the quality of our online connections that count.', 'Physiological effects of loneliness', 'Loneliness is not just a social issue, it also affects our health – so much so that in 2018 the Australian Government committed $46.1 million[ii] in 2018 to combating the issue. So how bad can it be? Increased blood pressure, cholesterol and risk of developing cardiovascular disease, plus reduced brain function, are all long-term side-effects of loneliness.', 'Research indicates that loneliness takes a toll on our mental health too. What’s tricky is that if you already have a mental health issue, the chance you will feel lonely is increased, while feeling lonely can also increase the severity of various mental health symptoms[iii].', 'How to reduce loneliness', 'It’s clear that reducing loneliness has health benefits, but this can be difficult to tackle when we are isolated, or already feeling less than our best. In Australia we are only just starting to undertake the research required to develop evidence-based solutions. In the meantime, it’s not as simple as surrounding yourself with as many people as possible – we need meaningful connections. The good news is that we can still create and maintain these social connections while most of us are currently spending more time at home[iv].', 'Below are some practical ways to start tackling those feelings of loneliness.', 'Make contact with others', 'When you’re feeling your most lonely, you doubt yourself, feel anxious socially, or are just unmotivated and want to be on your own. It’s almost counterintuitive to interact with others, but that’s exactly what you need to do.', 'John, one of our community presenters, has been doing this lately and recommends getting out of your comfort zone. “Get in touch with someone: a family member, workmate, neighbour. It’s quite likely they will appreciate a call.”', 'Another one of our presenters, Shai, has been finding time to socialise. “I have weekly catchups with my friends via Zoom and make sure I check in on those who might have lost touch for a while.”', 'Get creative', 'Youth presenter Georgina has been keeping busy, doing anything she can think of to occupy her time. “I have been studying, practising and making music, talking to my friends and family, watching movies and TV shows, reading, baking, and doing crafts!”', 'Natalie, another one of our youth presenters, has also been exploring creative hobbies.', '“I’ve been doing jigsaws, lots of jigsaws. I have bought candle making kits, and learnt how to do my nails properly, I’m cooking myself fancy things and baking my own bread. I’m exercising a lot; I get out for a couple of walks and fresh air. I’m reading a lot, sitting on my balcony in the sun with a book is relaxing.”', 'Volunteering', 'Volunteering allows us to make meaningful connections with people while establishing a sense of purpose. Studies[v] have shown the benefits of regular volunteering in reducing feelings of loneliness[vi] so why not give it a go? “You’re doing something beyond yourself which is even more satisfying,” says Rachel Cohen. Volunteering Australia is the national peak body and allows you to search for available positions based on your skills and location, and their initiative Go Volunteerhas lots of online and remote volunteering opportunities that are currently available.', 'Online groups', 'The internet offers a plethora of people from all over Australia that we can connect with instantly from the comfort of our own space. Facebook’s discover section allows you to browse groups by topic and covers everything from ‘sport and fitness’ to ‘science, technology and math’, so you are bound to find something that interests you. If you are living in a rural area you can even try creating your own.', 'For young people, Reach Out Forums provide a supportive, safe and anonymous space where you can chat to people online who are experiencing similar feelings as you.', 'Spend time with your animals', 'Pets, especially dogs, provide constant companionship and unconditional love – plus their need to be kept active gets you out of the house for essential exercise when you’re feeling down, Rachel points out. “They get you active and non-avoiding, while giving you a sense of purpose because you need to care for something beyond yourself.”', 'Get active', 'A 2017 study led by the Black Dog Institute showed regular exercise of any intensity can prevent future depression. Community presenter Nathan suggests getting out and making the most of essential exercise. “Get out an exercise! Not only does it release endorphins that promote positive feelings, but I find that simply being in nature can be calming.”', 'While tips like these can be a great start, don’t be afraid to seek help if you are struggling with the negative feelings of loneliness.', 'As Rachel says, “loneliness, depression and anxiety are normal reactions to abnormal circumstances, and this is nothing we’ve experienced before. It’s normal to feel this way and more common than you realize.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-loneliness/qotw0110-2/', '2021-01-11T12:00:00Z', '2021-01-11T12:00:00Z'),
  ('l6952', 'what-is-loneliness', 'awdhesh-s', 'name', null, array['Loneliness is hazardous to our health. It’s a shame that despite technology and access to anyone you wish available at our finger tips, people still complain about loneliness. People even write poetry on this topic and have glamorized it. While one may choose to spend quality time alone from the crowd for some time, too much alone time becomes a habit and then one becomes lonely which isn’t a good sign.', 'Solitary confinement was one kind of punishment and was considered worse than physical torture. This causes severe damage to the brain. It can make people mad.', 'Humans are meant to be part of a group.', 'Those who are lonely are also in some form of solitary confinement, which later results in mental health issues like depression.', 'It is understandable that nobody chooses to be lonely, however, part of the problem is the person who is lonely too.', 'People these days are just plain lazy to pick up a phone and talk to someone they know. Just a ‘Hello…hope everything is okay?’.', 'Most people seem to wait for everyone to inquire about them but nobody inquires about others. I have experienced this all my life too. I am yet to connect with anyone who would bother to inquire about me without selfish interest. That doesn’t stop me from connecting with new people.', 'However, I did not choose to be lonely. I do not believe that one must interact only with people of the age/social status same as theirs. I try to have small talks anywhere I go. Restaurant owners/people I meet in library and sometimes even strangers I meet at malls while waiting in the queue.', 'It is always advisable to have some human interaction. It need not be necessarily with your romantic interest.', 'Sometimes, people who feel lonely must do a self-introspection. What is it that is causing them to be lonely ? Is it their own self-esteem ? Are the people who hang out with not really reciprocating or ignoring them ? In such case, one must understand that not everyone is evil in the world. They must cut off people who ignore them and try to connect with people who are approachable.', 'Learn to make small talks. Just a sweet smile and ‘Hey…How have you been ?’ opens up the door for a conversation. Show some excitement in the conversation. Compliment others so that they like interacting with you. This will change the perception you have about yourself.', 'Never stay lonely for a long time. There is someone like you out there who has been waiting for a long time for a human, even a stranger, to just say ‘Hello, How have you been?’']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-loneliness/qotw0110/', '2021-01-11T12:00:00Z', '2021-01-11T12:00:00Z'),
  ('l6989', 'what-is-the-deepest-emotion', 'cnscsns', 'name', null, array['There is no answer to this question, as each emotion can be felt equally ‘deeply’. In other words, fully embodied love, fully embodied fear, fully embodied apathy, and so forth, are all equally deep emotions.', 'Picture each emotion as a magnet, pulling in a certain direction. Each shares a core essence – a complex coalescence of feelings. Depending on how these feelings come together determines the emotion, which in turn, affects our thoughts and actions.', 'We habituate to certain emotions, which plants the seeds and allows them to sprout more regularly in our life. The more we experience certain emotions, the more they influence our sense of identity and the lens through which we see the world. Thus, perhaps, one could argue that these emotions are one’s personal ‘deepest’ emotions, as they dictate our lives to the greatest extent.', 'Fear is the most common example of this point. Bombarded by fear-mongering in different facets of our modern society – from the media to scarcity-based economics, to rugged individualism – our garden is lined with weeds of fear. Thus, we become accustomed to experiencing our consciousness through a lens of fear and our thoughts and actions reflect this.', 'The universal law of cause and affect is that positive thoughts and actions yield positive results, and negative thoughts and actions yield negative results. Though there is no true judge of a positive and negative action, our intuition is pretty darn good at this role. Positive emotions – those of joy, gratitude, loving-kindness, empathy, and compassion – usually lead us to positive thoughts and actions. Negative emotions – those of fear, selfishness, anger and hatred – usually lead us to negative thoughts and actions.', 'While we cannot always choose what emotions arise in a given moment, we can choose to water the seeds of positive emotions when they arise, and alchemize the seeds of negative emotions. Take anger, for example. Someone cuts you off in traffic. This ‘negative’ emotion arises. Cultivating first, the awareness of that emotion – ‘I am experiencing anger’ – is fundamental. Next, make the choice NOT to continue to play out the story. Instead, take a step back and breathe. Third, the choice to access our wisdom and skillful means to use this experience as an opportunity for growth. ‘Oh, I experienced anger when that car cut me off. Why? What may have been behind the anger? Engage only as much as feels right, then let it continue to flow downstream.', 'Emotions are a profound and integral part of the human experience. They are like stars which guide us like boats through the night.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-deepest-emotion/qotw0117-3/', '2021-01-18T12:00:00Z', '2021-01-18T12:00:00Z'),
  ('l6986', 'what-is-the-deepest-emotion', 'akif-a', 'name', null, array['Of course, our perceptions of emotions are entirely dependant on our own mental approach to them, but personally, I would expect a large majority of people to agree that the deepest emotion a person could ever feel is “love”. This may sound quite cliche, but once going through the deep infatuation of love towards someone, one begins to understand just how vulnerable they are to being hurt and still be able to forgive.', 'A very powerful example of this (of which I am sure many people could relate to) is the inability to walk away which is caused by love. Many a time we may have somebody in our life who decides to leave us without notice or explanation, but as mad as we may be for them causing mental and emotional turmoil to us, we still fail to block them out and know would rekindle the relationship at the very first chance we are given to.', 'The power of love is also seen in family and God. It is a natural feeling for a person to turn to their most trusted circles at the time of dire need, majority of the time, these are also the people whom which we love. The deepness of sensation is seen here as we are able to trust others with the sincerest of our secrets and believe that they would not use that against us. Love.', 'To conclude, there has never been and never will be one emotion that can strive as the deepest, but for sure, the most commonly deepest emotion we all go through is undoubtedly love.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-is-the-deepest-emotion/qotw0117-2/', '2021-01-18T12:00:00Z', '2021-01-18T12:00:00Z'),
  ('l6982', 'what-is-the-deepest-emotion', 'mark-r', 'name', null, array['I believe there are two core emotions and they are opposites. One dissipates the other and vice versa. They are Fear and Love. They come in many more subtle forms like anger, sadness, happiness, playfulness, and everything in between. But you asked for the deepest, so I will try to speak to that.', 'I take your meaning of “deepest” is to feel as much and as hard as possible. Maximum Magnitude!', 'At one far end, you have complete and total terror. The most Fearful place you can imagine times 1000. A place where you feel, at the core of your being, absolutely disconnect from everything and every one and you are in life-threatening immediate danger.', 'At the other far end, you have complete and total Love. A place where you feel, at the core of your being, absolute connection to every other being and everything around you. You are as safe and complete, where nothing could harm you and you want for nothing. Loved and connected.', 'While absolutes are good for academics, our reality is thankfully not so extreme. Feelings flow and ebb and are very fluid. Fear and Love are opposing feelings, but I find there to be much overlap and nuance in the moment of actually feeling them. I have heard others describe these feelings as layers of emotions or several emotions at once.', 'These include Love and Fear simultaneously in varying degrees.', 'I have felt these on a few occasions. Like that time I helped my wife deliver our child, yup massive LOVE and FEAR. Most parents can relate. Getting married, duh. First job, first kiss, first … you get the idea. We feel them both often. We call them something else like jealousy or nurturing but its all fear or love, just different ways of going about it with some particular tilt or perspective taken.', 'If you want to feel the deepest emotions, you will need to get very comfortable with feeling both because you can’t just pick one side. It’s an ebb and a flow. Anyone who has had one of the proverbial “best days of my life” may have also noticed the happiness hangover in the following days. Typically the higher you go and the longer you’re there, the lower you will go and the longer you’ll be there. But I also think the cycle can be embraced and you can get the deep feels whenever you want. It’s one of those simple yet not easy conundrums of life. The best one in my opinion 🙂', 'Life is an experiment, test your self.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-is-the-deepest-emotion/qotw0117/', '2021-01-18T12:00:00Z', '2021-01-18T12:00:00Z'),
  ('l7009', 'what-are-synchronicities', 'k-t', 'name', null, array['A synchronicity is a moment in your life when everything lines up. You are given signs that you are where you’re meant to be. This can visit you in so many ways; receiving an unexpected gift that allows you to pursue something, even in a song that is playing in the street as you pass by. Sometimes this can be meeting people on similar paths as you or it can be represented within someone walking the opposite direction as you. When you meet someone who is on a similar path it can be an amazing support system that adds wider perspective and when you meet someone who is on an opposite path as you it can provide an inexplicable mirror into yourself and lessons that are unfolding. If your eyes are open to all of this, nearly everything becomes in sync.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-are-synchronicities/what-are-synchronicities-2/', '2021-01-24T12:00:00Z', '2021-01-24T12:00:00Z'),
  ('l7007', 'what-are-synchronicities', 'vigil-q', 'name', null, array['Synchronicity is a highly misunderstood word which was meant A: only to be tentative term for a principal which is better to be called acausality or transcausality which exists on a continuum with causallity and B: a permanent word for individual events of constellated meaning between the inner world of thought and the outer world of material where time and or space are a factor. Obviously not a simple subject and there is much more to be said, but it is not a school of philosophy from my view, but a principal as real as cause and effect.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-are-synchronicities/what-are-synchronicities/', '2021-01-24T12:00:00Z', '2021-01-24T12:00:00Z'),
  ('l7004', 'what-are-synchronicities', 'carder-s', 'name', null, array['Nothing happens by accident when your soul gets involved. It is the most intentional presence in your life whether you recognize its existence or not. Your soul is omniscient and ever present. It informs your decision making through the thoughts and images it provides. It is the essence that fuels your intuition. When you are certain of something it is your soul’s voice that resounds from the depths of psyche. When a mysterious coincidence occurs it is often the design of your soul’s whimsical nature. Yes, the soul has a sense of humor and often speaks to us through metaphors, symbols, riddles, and clues. These hints require our full investigation in order to uncover their meaning.', 'Synchronicity is a term that is frequently used to represent the process of experiences coming together and forming some sort of meaning. Synchronistic occurrences are formidable and propel us forward with a surge of ephemeral courage. Their bold numinosity fills us with a sense of awe and wonder and they leave the fray of untethered questions in our inquisitive minds. These are unexplained moments. We ask ourselves how certain events aligned in such perfect rhythmical order? We wonder how a circumstance tips in our favor right at the crucial moment we need it most. A person sways into our periphery and offers just the right words to push us from the gate of self-destruction. The 80’s song we were singing in the shower plays on our car radio that same morning. We stare in disbelief before singing it even louder. We wonder if there is someone behind the curtain. Synchronicities are incidents of spiritual significance that ask us to momentarily dampen our self-obsession and consider the possibility of the divine.', 'Synchronistic experiences leave us with a curious sense that we should pay attention. They happen when our inner worlds of thought and feeling connect with the outer world of people, places and things. If we think about something and then it appears there is a mystery involved that is both arcane and fascinating. Perhaps our soul is extending its collaborative spirit so that we may become aware of something that requires attention. Perhaps it is simply a coincidence. This depends wholly on what you are willing to believe. To claim certainty regarding such an esoteric concept would assert that we ourselves are wiser than the greatest minds of modern psychology. There are many conflicting theories that claim to define the nature of synchronicity. Scientists perform delicately balanced experiments in an attempt to capture its elusive meaning. Astrologers look to the stars for answers and create vast equations to define its erratic movements. Psychologists argue with physicians and claim jurisdiction over steins of darkened beer. Bible toting evangelists assert God’s will as the chanting mystics dance around the fire.', 'Carl Jung coined the term synchronicity in the early 1920’s. It was one of his most complex and misunderstood concepts, partially because it is an experience that forces people to question their notions of what is rational and scientific. Jung’s concept of a synchronistic world was a complex intertwining of linear causality forming a balance with the unseen energies of the universe, each complimenting the others in the realms of psyche and matter. In this conception, a playful relationship exists between what is seen and unseen. Jung hypothesized that synchronistic events were possibly the manifestations of a specific desire deriving from the humanistic need to heal and grow. He also believed that they were elements of a universal, archetypal pattern that helped connect people to the deeper truths of human existence. Jung stated that archetypes are born into consciousness as deliberate and intentional acts of the soul. It is my belief that synchronicities are also messages from this spiritual and authentic part of our being.', 'When I was 12 years old I got drunk for the first time. It was New Year’s Eve and my mother entrusted my brother and I to hold down the fort while she slipped into her sparkly shoes and headed to a masquerade ball. As soon as she left I began chugging cheap champagne in the second story bathroom of our house. I locked the door and began crooning Springsteen tunes before passing out on the floor. My heroic older brother climbed on an outdoor window ledge in an attempt to rescue me from myself. He fell two stories through a thorn bush and landed on a brick wall in our garden below. I awoke the next day with my first hangover and was informed that my brother lay in critical condition at Georgetown hospital. He had almost died on the operating table in the early morning hours with my mother by his side. I blamed myself of course. How could I have been so selfish? I was all alone in my guilt and wished that I had fallen instead of him. I walked outside into our garden and sat down on the jagged bricks where he had landed. The winter winds were blowing and a single leaf floated down toward me. I held out my hand and it landed gently in my palm. The leaf was in the perfect shape of a heart. At this moment, I knew that my brother was going to pull through.', 'I believe that synchronistic events are fashioned by the will of the soul. It is the soul’s aim to help us restore balance in our psyche. When we are overcome with psychological pain our soul steps in. When our strong emotions sweep us into the eye of the storm our soul reaches out in its unconventional ways. In these moments of despair, our soul may appear through the creation of a synchronistic moment. These occurrences are meant to help us pause and recognize that we are still alive. These are the hours when our faith is challenged and we need reassurance the most. Synchronicities are nudges from the deepest place of love that inhabits our psyche. They are torches in the darkest cave of the unconscious that allow us to glimpse that suffering will end. And it always does.', 'Synchronicity was instrumental in my own journey toward healing as well. In my late twenties I became severely addicted to drugs and alcohol. I sequestered myself to a small studio apartment in Venice, California where I frantically searched for my lost identity. I did not feel like I belonged in the world and was bereft of hope. I was in a deeply depressed state and felt like I could not go on. The voices in my head disallowed me to sleep so I paced frantically over the manmade canals of my neighborhood. And I seriously thought about jumping in. As I sat on the edge of the muddy banks a paperback book bobbed in the water beneath my feet. It was a poetry book by Pablo Neruda that someone had launched off a nearby bridge. I began to read the first poem and was immediately overwhelmed by its deliberate connection to my own life. The poem spoke about restoring hope through the recognition of small things. I peered to my left and saw a bluebird watching me. I raised my head and saw the sun rise over the palm trees. My sadness disappeared as I read the words. For the first time in many months I felt a calmness wash over me. That was the moment that I began a new way of life. It was the most important moment I have ever had. In that instant I believed that Neruda had written his poem just for me. I believed it with every fiber of my being. In that belief I found my voice again.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-are-synchronicities/qotw0124-2/', '2021-01-24T12:00:00Z', '2021-01-24T12:00:00Z'),
  ('l7001', 'what-are-synchronicities', 'gregg-l', 'name', null, array['I used to be a reporter for the Cincinnati Enquirer, back in my 20s, and for roughly half of my decade-long tenure there I kept hearing a call to quit and become a freelance writer, a decision I largely ignored for years because it was Scary Stuff. However, after years of trying to ignore this call, the signs pointing toward it took on a whole new tack. This is how it began:', 'I was driving home from work one day, listening to a song on the radio called “Desperado,” by the Eagles, and as I pulled up to the curb in front of my house, the last line I heard before I turned off the car was “Don’t you draw the Queen of Diamonds, she’ll beat you if she’s able; the Queen of Hearts is always your best bet.” I turned off the ignition, opened the door, stepped my foot onto the curb, and there at my left foot was a playing card—the Queen of Hearts.', 'I just sat there utterly dumbfounded, and wondering, of course, what it meant?', 'When I mentioned the incident to a friend that evening, she said, with an extravagant quality of assuredness, that when you’re on the right path, the universe winks and nods at you from time to time, to let you know. She also said that once you start noticing these little cosmic cairns, once you understand that you’re on a path at all, you’ll begin to see them everywhere. It’s what happened, she reminded me, when I bought my Toyota and suddenly started seeing Toyotas everywhere.', 'I didn’t know I was even on a path, I told her, much less whether it was the right one. I simply found myself unable to make heads or tails of the episode, and ended up filing it under “Unexplained Phenomena,” along with esp, deja vu, spoon-bending, water-witching, spontaneous remission, and certain incomprehensible acts of human forgiveness.', 'But even more remarkable than finding that Queen card when I did, was that over the next two years, as I searched for a sense of clarity (and courage) about this call, I found five more Queen playing cards, in incredibly improbable locations all around the country: a sidewalk in Cincinnati, a conference room in Santa Fe, a sand dune in Cannon Beach Oregon, a mountain wilderness in Colorado six miles from the nearest trailhead. The whole thing made the Twilight Zone seem like Mister Rogers Neighborhood.', 'And every time I found another Queen card, the sheer unbelievability of it took another giant step forward, and eventually, it went so far beyond the laws of probability that I only barely hesitate to say that it’s impossible there was nothing more going on here than a statistical aberration. This was orchestrated by something with wits. Which shot my rational view of the universe pretty much to hell.', 'I come from a family of scientists, detectives, journalists, non-fiction writers, and New Yorkers—and you don’t get a more cynical bunch than this—and this stuff just doesn’t happen in our universe. And yet, though the phenomenon became more inscrutable with each find, in a way it also began making more and more sense. A pattern—more, a passageway—seemed to emerge.', 'I came to understand that this rather profound administering of chance was directing me toward something both my writing and my life needed at that time: more heart, less head. More intuition, less intellect. More of the inner life, the emotional life, the life of the senses. More listening. More of what Carl Jung referred to as the anima, the force of the feminine in a man’s life. And the Queen, of course, is the archetype of powerful feminine energy, which I felt myself being compelled toward by the kind of meaningful coincidence Jung called synchronicity.article continues after advertisement', 'Synchronicities are events connected to one another not by strict cause-and-effect, but by what in classical times were known as sympathies, by the belief that an acausal relationship exists between events on the inside and the outside of ourselves, crosstalk between mind and matter—which is governed by a certain species of attraction.', 'Jung believed that synchronicities mirror deep psychological processes, carry messages the way dreams do, and take on meaning and provide guidance to the degree they correspond to emotional states and inner experiences.', 'For example, you’re trying to decide whether to say yes or no to a particular opportunity and while driving on the freeway someone suddenly cuts in front of you and you notice the bumper sticker: Just Do It!', 'Or you’re struggling to focus your energies, not spread yourself so thin and scatter your interests and attentions among too many projects, and while taking photographs one afternoon, you drop your wide-angle lens and shatter it.', 'You can derive meaning from “just a coincidence” when an external event matches up with an event on the inside. It doesn’t always. You might be sitting in a waiting room, for instance, reading a magazine article about George Gershwin, when the receptionist sticks her head out the door and calls for the next patient, a Mr. Gershwin, and as outlandish as this may seem to you, if it finds no hook on the inside, it’s not a synchronicity, only an amazing coincidence. If it means something to you, however, then it’s amazing and potentially instructive.', 'A synchronicity is a coincidence that has an analog in the psyche, and depending on how you understand it, it can inform you, primarily through intuition and emotion, how near or far you are from what Carlos Castaneda calls “the path with heart.” Among shamanic cultures, says anthropologist Michael Harner in The Way of the Shaman, synchronicities are considered “a kind of homing beacon analogous to a radio directional signal indicating that the right procedures and methods are being employed.”article continues after advertisement', 'In a movie called Grand Canyon, one of the sub-plots involves a woman who finds a baby, an event she believes is a reply to a deep yearning inside her—in other words, a synchronicity, a correspondence between a psychological state and a physical event. But when she tells her husband she wants to keep the baby, he’s instantly stricken with a migraine. In frustration, she leaps on top of him on the bed, grabs him by the shirt, and shakes him. “A headache,” she says, “is an inappropriate response to a miracle!”', 'Which was easy for her to say, since it was her miracle, not his, but she still had a good point. Synchronicities are minor miracles, little mysteries that point to a bigger one, perhaps a central one, of which we’re all a part. In contemplating synchronicities, don’t just marvel at the laws of probability, but wonder at their meaning. “The primary reality of synchronicities is emotional, not intellectual,” says Mark Holland, co-author of Synchronicity. “The reason they’re there is to make us feel something, and the feeling that our lives are rich and worth our reflection comes in part from our sense of the depth and mystery of life.”', 'In fact, maybe the most important thing synchronicities offer is astonishment. How often, after all, in the course of a day or a week or a month, do you find yourself thunderstruck, flabbergasted at life, amazed by its finesse? Synchronicities are like the glimpse of a wild animal seldom seen, the discovery of an arrowhead or a geode, the return of your purse by some good Samaritan. Far removed from the mundaneness that seems to characterize such a vast portion of daily life, they help reconnect you to your sense of awe, and given the tyranny of the commonplace, what a service!article continues after advertisement', 'No one has been able to fully explain synchronicity, so perhaps you should simply accept it as a wild card and an ordering principle, the height of absurdity and the depth of profundity, and a crack in the door through which you can catch sight of the universe and its mysterious ways.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-are-synchronicities/qotw0124/', '2021-01-24T12:00:00Z', '2021-01-24T12:00:00Z'),
  ('l7042', 'why-suffer', 'rashad-r', 'name', null, array['I dare not make a generalization about others’ suffering, and shall thus speak only of my own experience. For years, I have asked myself the question: Why do I continue to choose suffering … EVEN while knowing that there exists another option. My conclusion, thus far, parallels my view of the basic structure of the Universe: It’s play. It’s exploration. Suffering, like any dark, deep place, can be explored, excavated, etc. I have settled on the idea that I am not yet done exploring this space, and will continue to do this work / play until the path of least resistance is to leave it.', 'I believe that the Universe is exploring itself through various forms of consciousness, and humans have been endowed with the ability to suffer to profound and extraordinary depths (among other endowments). As with anything else, the existence of a force elicits a counter-force, and to try to impose a force of ending suffering will naturally create an oppositional force of prolonging and deepening that suffering. Only when the natural current washes us out of suffering naturally, can we actually transform into wellbeing.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/qotw0131/qotw0131-3-2/', '2021-01-31T12:00:00Z', '2021-01-31T12:00:00Z'),
  ('l7037', 'why-suffer', 'cooper-r', 'name', null, array['I suffer because I think. It really can’t get much simpler than that. Now what do I mean by this? Well, I mean that I over analyze everything.', 'For example, regardless of which worldview one adheres to, there really isn’t a good reason as to why the universe is, and by extension why we are. If you’re religious you can say that a creator did it for their own pleasure, and that we were created in our current form. If you’re non-religious, then you’d probably say that the universe was created by quantum fluctuations in an empty void, and through cosmological trial and error, got to us over a large span of time.', 'Now that we have a back story, what do we do with it? Well we use our brains to make tools and to organize ourselves into groups by similarities and differences in beliefs and abilities. These are social groups. And a network of many social groups is called a society. Now we’re getting somewhere! In these societies, people (who will adhere to a certain worldview depending on their environment and social interaction) will be subject to arbitrarily defined rules that tell them how to behave, and are enforced by threat of punishment.', 'Depending on how strongly they feel about these rules, some groups will try to impose their beliefs onto other groups leading to conflict. Sometimes these conflicts are more about the fact that resources that are available naturally to one group, should be available for another. If these conflicts are large enough, they are called wars. Vast amounts of resources are then dedicated to “winning” these conflicts. Are they important? It depends on who is asked.', 'Now, if you want to have access to resources within a society you wil need to subscribe to the arbitrarily defined value system and rules of behavior for that society. These are otherwise known as economics and law respectively. However, in order to have basic access, you’ll need to have a knowledge/skill set that you can perform repetitively in order to amass enough value to demonstrate that you should indeed have access to a resource. In order to get a job, it is beneficial to have a piece of paper (attained from a place of learning) that tells the place of work, that you meet the requirements of the job. Some of these “jobs” allow one to amass more value quicker than others. And what does this increased value offer? Well it allows one to exchange parts of their amassed value for material objects and experiences. It also bestows upon the individual “status” or a false sense of increased importance. Which often leads again to conflict.', 'On top of all of these things and more, if you don’t complete arbitrarily assigned goals at points in your finite time here (oh yes, there’s a time limit to all of this) then you are automatically assigned less worth by the society as a whole.', 'In the end, the way you live, affects how others live and will live. So be kind, accept your differences and try to appreciate the time you have on this little blue marble we call “earth”.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/qotw0131/qotw0131-3/', '2021-01-31T12:00:00Z', '2021-01-31T12:00:00Z'),
  ('l7034', 'why-suffer', 'paul-b', 'name', null, array['Just the word brings up images of death, despair and agony. It may remind us of the worst times we’ve experienced in life: loved ones we’ve lost, relationships that broke up despite all our best hopes, feelings of loneliness and deep depression. As soon as we’re old enough to know the first hints of suffering from hunger and cold to jealousy or abandonment most of us start seeking the quickest possible antidotes to that suffering. Our physiological and instinctive reaction to pain and suffering is to escape it. When you touch a hot stove your hand will be pulled back before you even consciously realize it. But facing suffering in our conscious mind can be even harder. That’s because we want to either get rid of the suffering or make sense of it and sometimes neither of these options is possible. That’s where facing and accepting suffering becomes the only option.', 'What is suffering?', 'The fact is that suffering is an inevitable part of life, from aging and death to heartbreak and disappointment.', 'Physical suffering is pain, aging, deterioration and injury. Emotional suffering is betrayal, sadness, loneliness and feelings of inadequacy or blind rage.', 'Where suffering becomes even harder, however, is in our minds and in the stories we make about it.', 'Faced with the painful reality of suffering many of us try to make sense out of it in a framework we can understand: we ask questions and struggle with the idea of fairness, for example, or situate difficult experiences and trials within a religious or spiritual context.', 'Many even cling to false ideas about the meaning of karma in order to reassure themselves that suffering is happening for a good or “justified” reason.', 'Our technologically-advanced Western societies often respond to death and suffering by banalizing and trivializing them. We try to escape the trauma by denying it really exists in the first place.', 'But the fact is that this is never going to work.', 'Suffering is part of existence, and even the most picture-perfect life on the outside often has a deep core of pain in the past which you know nothing about as an outside observer.', 'As DMX puts it — quoting Nietzsche — in his 1998 song “Slippin’:”', '“To live, is to suffer.', 'To survive, well, that’s to find meaning in the suffering.”', 'Here are ten aspects of suffering that can help you to lead a fuller life:', '1. Only know you’ve been high when you’re feeling low', 'The fact of the matter is that you aren’t going to be the first person in history who avoids any suffering.', 'Sorry to break it to you.', 'But suffering is the price of the ticket for this ride we call life.', 'Even if you try to shut down whatever suffering you think is under your control it won’t work. For example if you’ve been let down in love and put your guard up you may miss out on the next chance for a loving partner, leading to years of regret and loneliness.', 'But if you’re overly open to love you may get burned and have your heart broken.', 'Either way you have to take a risk and you simply must accept that suffering is not optional.', 'The more you try to dodge rejection or get an easy go of it in life and love the more you are going to end up on the sidelines. You can’t just guard all your emotions and become a robot: and why would you want to anyway?', 'You’re going to suffer. I’m going to suffer. We’re all going to suffer.', 'You only know you’ve been high when you’re feeling low. So don’t shut down the whole production just because you’re getting hurt: either way it’s going to continue and your only real choice is whether to be a proactive partner in life or a reluctant prisoner being dragged behind a horse.', '2. Let the pain push you forward', 'Nothing is going to hit you as hard as life. And there’s going to be times that leave you literally on the floor.', 'Being overly happy about that or full of toxic positivity is not the answer.', 'You won’t get rich after bankruptcy by “thinking positive,” you’ll get it by digging down to the roots of how you approach money and your relationship with yourself and your power.', 'The same thing goes for the big and small traumas of life.', 'You can’t choose them, and even if your choice contributed to something that’s happened and caused you suffering it’s now in the past.', 'The only freedom you have now is to grow from the pain.', 'Let the pain reshape your world and hone your determination and grit. Let it build your resilience and fortitude in the face of suffering.', 'Let the fear and despair take you into your core and find the healing power of your breath and the life within you. Let the situation around and within you that seems completely unacceptable be met with acceptance and strength.', 'The post-pandemic world will be shaped by how we react to fear, and that journey is already underway.', '3. Suffering can teach you humility and grace', 'If you’ve struggled with asthma then you know how incredible it can feel to take a deep breath without any trouble.', 'If you’ve experienced the worst heartbreak then you know how finding lasting and real love can make you feel.', 'Suffering can take us lower than the rocks and reduce us to less than we ever thought possible.', 'The suffering of war has reduced human beings to mere skeletons. The horrific suffering of cancer has turned once vibrant men and women into physical husks of their former selves.', 'When we suffer we are forced to drop all expectations and demands. It can be our chance to notice even the smallest positives that still exist, like the kind person who comes to visit us as we recover from a devastating and nearly fatal addiction, or the old friend who brings over food after a painful loss of our partner.', 'In the depths of suffering the miracle of life can still shine out.', '4. Suffering can help you hone your willpower', 'What I mean is that even a flower growing up through the sidewalk crack has to struggle and feel pain to bloom.', 'Anything you accomplish has some pushback and life is a dynamic – and sometimes painful – process.', 'Although some people may seek out suffering as part of a spiritual or religious path (which I discuss below), generally it is not a choice.', 'However, how you respond is a choice.', 'You can actually use suffering and the pain you have been through to hone your willpower.', 'Let suffering and the memory of it be the catalyst that allows you to become a more powerful person: powerful at helping yourself, powerful at helping others, powerful in accepting the sometimes harsh nature of reality.', '5. Why does this sh*t always happen to me?', 'One of the worst things about suffering can be the feeling that we’re all alone.', 'We start to internalize the idea that suffering has come to us for a bigger reason or some kind of “guilt” or sin we have committed.', 'This idea can be linked to religious systems and philosophies as well as an inbuilt tendency of sensitive people to blame themselves and seek the answer to disturbing things that happen.', 'We may push down our own vulnerability and believe that we have somehow “deserved” our suffering and must suffer through it on our own.', 'An opposite but equally harmful reaction is to treat suffering as personalized: why does this sh*t always happen to me? we shout.', 'Our mind tries to make sense of awful things that happen by either blaming ourselves and thinking we deserve it or by believing we have been singled out by some cruel force that picks on us for no reason.', 'The truth is you are neither exceptionally bad and “deserving” of suffering, nor are you the only one who’s being rained down upon with holy vengeance.', 'You’re experiencing suffering and pain. It’s hard and it is what it is.', '6. Suffering can be your window onto a brighter world', '“Tell your heart that the fear of suffering is worse than the suffering itself. And that no heart has ever suffered when it goes in search of its dreams, because every second of the search is a second’s encounter with God and with eternity.”', '– Paulo Coelho', 'Suffering is generally something we categorize along with other undesirable and awful things in the corner of our mind.Sponsored by MerckEl juego SMASH PackagingPon a prueba tu dominio de la sustentabilidad y descubre cómo nuestro programa SMASH Packaging minimiza la huella ecológica. #alwayscuriousSEE MORE', 'On one side you have victory, pleasure, love and belonging, on the other you have defeat, pain, hate and isolation.', 'Who would want any of that negative stuff?', 'We push away these painful and difficult experiences because they cause us suffering.', 'But suffering is also one of our biggest teachers and all of us are going to be getting to know it in one form or another for the rest of our lives.', 'Why not pull up a chair and order a drink?', 'Suffering is going to be sticking around either way. And sometimes the sweat and blood and tears can be the haze that comes before your greatest triumph.', 'Sometimes the gut punch that lands you in ER at age 16 from a drug overdose can be the experience you look back on 20 years later and see was absolutely necessary for the mission you eventually had to help others through their own struggles.', 'Suffering is no joke – nor should you “want” it – but it can end up becoming your window onto a brighter world.', '7. Suffering can deepen your faith and spiritual life', 'Suffering can deepen our faith and spiritual experiences.', 'All life suffers in the literal sense. Organisms feel cold and hunger, animals being hunted feel fear. Humans have consciousness of death and fear the unknown.', 'Along the path of life people respond in many ways to the unknown and their own inner life.', 'The Syrian Christian hermit Saint Simoen Stylites (Simon the Elder) lived on a one-square-meter platform atop a 15-meter pillar for 37 years because monastic life was too extravagant for him in his quest for higher meaning. Food was brought up to him by a ladder.', 'In the pain of suffering some individuals are able to find a cleansing fire. They are able to use suffering to burn through the layers of illusion inside themselves and enter the present moment in all its imperfection and pain.', 'Instead of suffering increasing the desire to no longer exist, spirituality and inner experience can be strengthened and suffering can bring us to a stronger determination and drive to be present and exist.', '8. Suffering can increase your compassion for others', 'When we experience suffering – or even choose it as some monks and others have – we begin to deeply appreciate the immense hardship that many people around us are experiencing. We empathize more and we want to help, even if it is just to be there for them.', 'Having compassion and empathy for others also involves starting by having compassion and empathy for ourselves. Before we can truly find love and intimacy with others we must find it within ourselves, and before we can hope for compassion and reciprocity to flow toward us we must become the engine of it ourselves.', 'Suffering and trials of life may increase the lines on our face, but it can also strengthen the kindness inside of us. It can forge an unbreakable authenticity and desire to give back that nothing can break.', 'When you’ve experienced the very worst of life you realize that truly one of the greatest gifts and opportunities is any chance make someone else’s time on this planet just a little bit better.', '9. Suffering can be a valuable reality check', 'Instead of constantly hearing that “everything is going to be OK” or to “think positive,” suffering can be a painful reminder and reality check that no, not everything necessarily is going to be “fine” at least not in an immediate or literal way.', 'Would you rather the truth or comforting lies?', 'The problem is that even if you said comforting lies once you know they’re lies they won’t satisfy you.', 'Regardless of your faith or level of optimism there are tragedies, setbacks and challenges which happen in life that can stun even the strongest of us.', 'There are experiences that can haunt you for the rest of your life, from being a refugee in war to watching a loved one die.', 'Running away from that or pretending it’s “not so bad” won’t help you or anyone else. Taking that pain and accepting it and seeing that it’s as much part of reality as the good things is the only real option.', 'There can be times when accepting that life sucks right now can actually lead you to stop chasing fairytales and codependent relationships and reclaim your personal power.', '10. When the going gets tough, the tough get going', 'The truth is that life is hard and sometimes even downright overwhelming.', 'As much as you may want to give up – and even sometimes temporarily do – you need to get back up and keep moving. More people are depending on you than you know, and some of the greatest figures in history who have made the world a better place struggled deeply in ways that most of us couldn’t even imagine.', 'The blind French author Jacques Lusseyrand heroically fought against the Nazis in the French Resistance and was imprisoned at Buchenwald camp, but never lost his faith that life was worth living. Sadly, life had other plans and in the summer of 1971 at only 46-years-old he was killed along with his wife Marie in a car accident.', 'Life hits hard, and it’s often deeply unfair. Repressing or justifying that won’t change that fact.', 'Figures who many admire from Abraham Lincoln and Sylvia Plath to Pablo Picasso and Mahatma Gandhi struggled enormously. Lincoln and Plath both had severe depression and suicidal thoughts, while Picasso lost his sister Conchita when she was only seven from diptheria, despite promising God he would give up painting if He would spare the sister he loved so much.', 'Life will take all your assumptions and hopes and throw them out the window. It will make you suffer more than you ever thought possible. But through it all there is a shred of faith, strength and hope that will always be there deep inside.', 'As Rocky Balboa says in the 2006 film of the same name:', '“You, me, or nobody is gonna hit as hard as life. But it ain’t about how hard ya hit. It’s about how hard you can get hit and keep moving forward. How much you can take and keep moving forward. That’s how winning is done!']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/qotw0131/qotw0131-2/', '2021-01-31T12:00:00Z', '2021-01-31T12:00:00Z'),
  ('l7031', 'why-suffer', 'rabbi-alan-l', 'name', null, array['As a Rabbi, I’ve found that the most troubling spiritual question for most people is: “Why is life so difficult?” They want to understand why bad things happen — especially to good people — why things can’t always be easy and comfortable and why we suffer. This question of suffering — which theologians refer to as “theodicy” — has, since the emergence of human consciousness, prompted many different theories and possible answers. Below are three compelling ideas. Some may resonate for you and others may seem forced or flat, but all present a way to see life’s difficulties as mechanisms for growth.', 'The first idea may be stated as:
Overcoming Difficulties Elevates Us', 'The ancient Greek philosopher, Epicurus, stated:', 'The greater the difficulty, the more glory in surmounting it. Skillful pilots gain their reputation from storms and tempests.', 'In other words, by responding to challenges we develop skills and the effort of hard work and well-earned accomplishments develops self-esteem. I read a wonderful allegory about this idea:', 'There was a man who loved to golf, but did not have the time to practice, so he was constantly frustrated by his mediocre game. Finally, he calls out to the heavens, “Please, God. If only I could hit a hole-in-one every time, I would be happy.” He hears a voice respond, “You’re desire is granted.”', 'The man hits the ball, and it sails right in to the hole. He swings again, and the second ball lands on top of the first. Elated, he calls to his friends, and they are amazed at his new powers. He goes on tour, and becomes famous and rich. But the novelty quickly wears off, and people soon become bored watching the same results every time: every swing, a hole-in-one. The man too is now bored, and he begins to hate the game that he once loved. He tries to deliberately miss so that the game will be more interesting, but no matter where he swings, the ball finds the hole. Finally, he returns to the golf course where he received his wish, and throws his clubs into the lake.”God,” he cries, “why did you grant me this foolish wish?” THE ESSENTIAL GUIDE TO TAKING CARE OF YOUR MIND AND BODYSubscribe to HuffPost’s wellness emailSuccessfully Subscribed!Wellness delivered to your inbox', 'The voice replies, “Who said I was God?”', 'The second approach to understanding life’s difficulty may be stated as:
Difficulties Present the Necessity for Choices', 'The 17th century German philosopher Gottfried Leibniz wrote that the world in which we live is the “best possible world.” This statement is often misunderstood to mean that the world is as good as it could be. What Leibnitz teaches, though, is that this system, which presents adversity and allows for the possibility of suffering, is necessary so that we can choose the good. We may wish to live in a Garden of Eden where there is no struggle and no need to grow, but such a world can never be as good as the potential that exists in our world. The wonderful movie Wall-Epresents the horror of a pleasure-cruise, no-struggle world.', 'Difficulties are necessary so that we can make choices. Through choosing between compassion or anger, action or resignation, or generosity or selfishness, we literally create ourselves. Without the possibility of adversity, these choices would not be needed and we would remain blank slates. It is through difficult choices, and the effort required to implement these choices, that we become agents for personal and societal growth, or apathy and decay.', 'The third approach to understanding life’s difficulty may be stated as:
Difficulties Develop Confidence and Faith.', 'How often have we faced a situation that seemed like a disaster — that made us cry out, “Why is this happening to me?” — only to find later that this “disaster” was actually exactly what we needed at that moment to protect us, guide us and perhaps push us towards a higher goal that we would not have moved towards otherwise.', 'At the end of the movie “Charlie Wilson’s War”, the CIA agent who has been working with Congressman Wilson to overthrow the Soviet occupation of Afghanistan, looks back on the operation (which eventually led to the tyrannical rule of the Taliban and the training of international terrorists), and tells Wilson a story: 
There was once a Zen Master who hears that a boy has been given a horse.
“How wonderful,” the people shout. 
“We’ll see,” says the Zen Master. 
Then the boy falls off of his horse and breaks his leg. 
“How terrible,” the people cry.
“We’ll see,” says the Zen Master. 
Soon a war breaks out, and the boy is spared from service because of his broken leg. 
“How wonderful”, the people shout. 
“We’ll see,” says the Zen Master.', 'As the Zen Master taught, we usually don’t have the perspective to understand the long-term significance of events that occur in our lives. By remaining open to the possibility that we simply don’t know, we learn to let go of our immediate response to classify and judge, and thereby develop faith — which is the existential confidence in the goodness of ourselves and the world.', 'It is important to understand that these approaches are not intended to diminish the feelings of pain and loss that come from tragedies. Here, we are called to respond with compassion and a desire to help. Once we accept the truth that life’s difficulties are the mechanism for growth, though, our resistance to the events that occur in our lives will begin to soften, and we can experience life with openness to new possibilities.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/qotw0131/qotw0131/', '2021-01-31T12:00:00Z', '2021-01-31T12:00:00Z'),
  ('l7064', 'what-makes-good-art', 'helen-l', 'name', null, array['What makes an artwork good? When it adheres to design principles?
If it looks true to life?
Should it turn our worldview upside down?
Must it fill us with emotions?The issue of what makes an artwork good has probably been debated since the first splotch of pigment touched a cave wall. It is nearly impossible to define what art is, so when we start discussing what makes an artwork impressive or worthy or good, we wade into complicated waters. Ask a group of students whether an individual artwork is good or not and you’re likely to get conflicting answers. Ask them what makes an artwork good or not and you’ll get as many answers as students you question.', 'Many art theories have emerged to encompass the wide variety of ideas and opinions about what art is and what it should do. The search for one art theory to rule them all may be futile, but there are arguments to be made on all sides, and everyone has a favorite.', 'Art Theory: Formalism', 'Wassily Kandinsky, Squares with Concentric Circles, 1913', 'Formalism dictates that art is good when it effectively uses the elements of art and principles of design. A formalist will concentrate solely on how an artwork looks–color, line, shape, and texture. The story being told and any historical or social context behind the artwork has no bearing on whether it is considered successful. The composition is all that matters. While artists have always used the elements and principles of art, formalism really came into being with modern art and the rise of abstract and expressionist works since those pieces put special emphasis on using line, shape, and color to create a pleasing composition.', 'Art Theory: Imitationalism / Mimetic', 'Johannes Vermeer, The Milkmaid, 1658', 'The imitationalism or mimetic theory of art claims that artwork is best when it imitates life. We’ve all experienced seeing an artwork from a distance and mistaking it for the real thing, rather than a replica. Those pieces are prized under imitationalism. The most realistic, the better.', 'In Vermeer’s The Milkmaid, we see the creamy milk pouring from the jug. It’s easy to imagine the splashing sound it makes hitting the bottom of the container. The texture of the baskets and the woman’s clothing look real enough to reach out and touch. The play of light and shadows match what comes through our own windows. We don’t have to make any mental leaps to imagine the scene unfolding right in front of us. Mimetic artworks are instantly recognizable because of their devotion to reality.', 'Art Theory: Instrumentalism', 'John Heartfield, Have no fear–He’s a Vegetarian, 1936', 'An instrumentalist is not concerned with composition, only context. Through the lens of instrumentalism, the best artworks are those that convey a message or shape how we see the world. Unlike other art theories, instrumentalism says that art is good when it functions as a tool to influence or change society.', 'The artwork above no doubt drew a visceral reaction the moment you saw it. Did your eyes flick to the title? Were you trying to figure out what the artist was trying to say? Now imagine that you saw this artwork before World War II. As Hitler rose to power, many saw him as a harmless politician, though some knew otherwise. In this piece, Heartfield was using his art as an instrument, sounding an alarm for anyone who thought Hitler was nothing to fear.', 'Art Theory: Emotionalism', 'Franz Marc, Fate of the Animals, 1913', 'The emotionalism theory places emphasis on the expressive qualities of an artwork. The communication between artwork and viewer is crucial. If the art is able to elicit a feeling from the audience, then the artist has created an excellent piece. Emotionalism is unique among art theories because it is not concerned with how an observer is attracted. Varying components of an artwork can captivate different viewers, but it only matters that the artist was able to evoke a mood or idea, regardless of composition, context, or narrative.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-makes-good-art/qotw0207-3/', '2021-02-07T12:00:00Z', '2021-02-07T12:00:00Z'),
  ('l7061', 'what-makes-good-art', 'jessica-s', 'name', null, array['What does it take to make a great piece of art? This seemingly simple, yet deeply complex, question has been debated throughout the history of art. Who decides what is “good” art and what is “bad” art? While many look to art critics and curators for answers, we decided to turn to a wide variety of contemporary artists, going directly to the source.', 'From illustrators to paper artists, photographers to installation artists, just what do the creative minds behind today’s most stimulating contemporary art feel is the key to great art? For many, it’s subjective and can encompass a range of characteristics, but as we surveyed the artists there were overarching themes. Innovation, emotional connectivity, and a bit of luck were repeatedly mentioned no matter the medium.', 'The eternal quest for great art of course changes over time, ebbing and flowing with tastes and trends. So, let’s take a look at how these 21st-century artists respond when posed with this challenging question.', 'We asked 12 contemporary artists “What does it take to make a great piece of art?” Here’s what they said…', 'Li Hongbo. READ MORE: Astonishing Stretchable Paper Sculptures Appear to Be Made of Stone', 'Li Hongbo', 'When I first started practicing art, our professors would make us draw the busts of widely renowned sculptures. The busts became patient friends and mentors of mine. To this day I will remember the time I spent sketching them. To breathe new life and revitalize old memories, I have recreated these tools of study using my own mode of expression—paper.', 'My artistic creation has lots of themes. However, they are all close to my thinking, my experience, and my life now. Those themes, which have been expressed, are the material, which comes from my inner thinking. When people look at a box, they think “It’s a box.” But, actually, it can change into another thing. I want to change the image, change how people see things so they think in another way, and more deeply.', 'There is a Chinese saying, “life is as fragile as paper,” which has left a deep impact on me. The concise and harrowing phrase sums up the fragility of life and rockiness of fate. Life is as pure as a piece of white paper when it is born. Yet, it is as fleeting as a galloping white horse against infinite time, as it is fragile and solitary against the volatile world. Life is vulnerable and transient; it is as fragile as paper.', 'Maybe I am like paper: pure at birth, silent in death, and blossoming like flowers even in my withered bones.', 'Rebecca Louise Law. READ MORE: Giant Installation of 150,000 Native Australian Blooms Displays the Power of Flowers', 'Rebecca Louise Law', 'Patience, courage, humility and hard work. I have found that focusing ahead is much more beneficial to my art practice than looking at the present. Living in the moment can be distracting and often hinder the creative process. The best work always comes from being challenged, whether in time, finances, materials or concept. It’s better to take risks than play safe.', 'Federico Babina. READ MORE: Powerful Architectural Illustrations Visually Interpret Mental Illnesses', 'Federico Babina', 'In everything, there is a bit of ART. There is, you have just to discover how to see it. It is often hidden, fragmented, disorganized, and unassuming. The challenge is to discover it, compose it, and order it. We should observe things from a different point of view. Looking at the world upside down can offer many creative ideas and awaken from a kind of “sleep of vision.”', 'There is no universal formula to create a piece of art. Everyone has to find their own path. Your traveling companions on this journey through these sensitive places are “fARTasy,” “creARTivity,” and “invARTiveness.” It is like composing a song or a melody. The notes already exist and they are seven. The hardest part is putting them together and finding a proper balance between the music and the silence, between harmony and melody.', 'Matt Shlian. READ MORE: Artist Uses Engineering to Fold Mesmerizing Geometric Paper Sculptures', 'Matt Shlian', 'This feels like a trick question. It can be interpreted as what (tools, materials, process) does it take to make a great piece of art? Or it can be read as what makes a piece of art great? Both are big questions.', 'Let me start with what makes a piece great:', 'A piece of art needs to connect. It needs to have some element of truth to it that resonates with the viewer and leaves them something after they’ve left the piece. A good piece asks questions and teaches you something you didn’t know or shows you something you didn’t know you knew. It articulates something we’ve felt, and we connect to that thing in a way where words aren’t necessary. It’s a feeling that’s hard to describe but makes us feel less alone in a way—that someone else understands us and gives a voice to this thing inside us. A piece of art extends beyond its frame and becomes part of us.', 'I’ve made work for almost 20 years and I’m made a ton of work in that time. Some are ok, most “meh,” and a handful of good ones. The ok ones lead to the next pieces (and are a necessary part of the process) and the good ones sometimes come all at once and sometimes you have to grind them out slowly for a number of years to get one. It’s equal parts mining for gold and standing in a field trying to get stuck by lighting. Some days you dig and other days you look up and wait.', 'This leads back to the first question—What does it take to make a great piece?', 'It takes time, sometimes a shovel and sometimes it takes being in the right place at the right time.', 'Rone. READ MORE: Street Artist Creates Crumbling Portraits on Abandoned Buildings to Reveal the Fragility of Beauty', 'Rone', 'I think what it takes to make a great piece of art is to connect with the observer on an emotional or personal level. A bit of mystery can let the observer interpret the work based on their own experiences and let them identify with it. If you spell it all out there can only be one way to interpret the work, and I think what makes great art is when everyone experiences it differently.', 'Miguel Chevalier. READ MORE: Projection Mapping on King’s College Chapel Blends 16th-Century Gothic Architecture with Contemporary Art', 'Miguel Chevalier', 'In my case, I understood in the early 1980s that computer tools were going to be the basis for a structurally original approach, whose stakes had to be grasped right away. These possibilities seemed unlimited and the transformations unending. They represented a fabulous dictionary of forms and colors, on whose basis I could work on the image, modify it, and regenerate it.', 'Digital art can explore new territory. I believe that is really a new kind of aesthetic of the virtual that is emerging. I have the feeling of being in tune with my time, creating a new poetry and a new poetic universe able to lift emotions. It is for me the art of the 21st century.', 'Sigalit Landau. READ MORE: Dress Submerged in Dead Sea Transforms Into Glimmering Salt-Covered Masterpiece', 'Sigalit Landau', 'To make a great piece of art you need to believe that you have an eternity of time—even though it is the most urgent thing in your life—and you also need plenty of nothing-to-lose, for its impeccable production. To consume a lot of music, love, and a little alcohol, of course.', 'Omar Z. Robles. READ MORE: Dynamic Photos of Ballet Dancers in Motion on the Streets of Puerto Rico', 'Omar Z. Robles', 'It takes a larger combination of elements to create one great work of art, but ultimately the question should become “What does it take to make a great PIECES of art?” (Note the plural). Why? Because in order for an artist to truly excel they need to be able to create not one, but many great pieces of art. That’s how you can recognize, or rather distinguish, the artist from the layman. It’s the consistency in their work that separates them from just being a “one hit wonder”.', 'Now in order to achieve that, you need to be able to have the patience of going through the process of getting it wrong, many times. Until you start getting it right, then you continue pushing yourself on that same line and you don’t quit. Another element is to be self-critical. One of my mentors in photography once told me “the true secret to great photographers is that they only exhibit their best work.” We all can produce a bad piece, even on our best days. However, you have to learn to detach yourself from your work and be critical of yourself before you publish any kind of work.', 'Finally, it takes essence/context for a work to be great. That is, I guess, the hardest thing to assess. Great works of art, I believe, all share one thing, and that is that they are supported by context. It can’t just be beautiful, or shocking for the sake of it. Great artworks captivate you because you can, in one way or another, identify with it. Marcel Marceau used to tell me all the time “il fault toucher le publique” (we need to be able to move the audience). His message was, it’s not enough to be technically good, you need to have the capability to move and touch your audience. The only way you can move your audience is if your work is supported by context.', 'Charles Pètillon', 'Great authors, philosophers, or critics have published books about this subject without being able to answer the question, so I do not see how I can try to answer it….. The look on a work is multiple. There is an emotional and philosophical charge, the relation to space, the subject, the light, the relation to the spectator, the technique, the message, the concept etc ……', 'Lauren Brevner', 'Every time I see work from another artist that I love, I tend to have a visceral reaction to the piece(s). It could be a quickening of my pulse, or butterflies in my stomach, that strange twisty feeling you get in your gut that’s so similar to the reaction you would have when lusting over someone. That’s how I know it’s good. I can’t stop smiling, or staring; it brings me such a rush of emotion that I can’t help but feel drawn to it. I believe it comes down to a purity of the artist’s voice that you really can’t fake.', 'When making my own work, I know I’ve done my job when I get that feeling, that twinge of excitement (of course that doesn’t always happen, unfortunately) but I know I’ve done my best when I have those feelings.', 'Philippe Echaroux. READ MORE: Powerful Series Projects Faces of Indigenous People Onto the Amazon Rainforest.', 'Philippe Echaroux', 'An emotion. This is the first spark of every fire. Emotions that are not necessarily positive ones, but this first feeling creates the art. If you try to express what you are feeling that will be art no matter which way it takes and what form it has.', 'Loreal Prystaj. READ MORE: Surreal Portraits of the Human Form Hiding Behind Reflections of Nature', 'Loreal Prystaj', 'As an artist, it is important to create work that genuinely comes from within. This is the only way that a new and unique point of view is found. It is an easy trap for an artist to generate work she perceives her audience will like. True, the viewer ultimately determines the greatness of an art piece—great art impacts a vast spectrum of people. But a volatile audience cannot be predicted, hence great art is rarely a calculated guess, it is often an accident. The only way an artist can introduce new perspectives is continuing to be curious, ask questions, and explore. Seeing the world through curious eyes leads to new discoveries.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-makes-good-art/qotw0207-2/', '2021-02-07T12:00:00Z', '2021-02-07T12:00:00Z'),
  ('l7057', 'what-makes-good-art', 'alina-l', 'name', null, array['Often we stand before a beautiful painting while watching your friend say “not my favorite. I mean it’s good, just doesn’t feel like special.” You raise your brow as your friend turns his attention towards another painting. You think how could he not like this piece, so cool and the colors are great.Eventually, you ask yourself – what makes art good?', 'Many questions arise while thinking of what makes good art:', '– Is someone more refined than the other?
– Did personal experience shape the perception of the piece? 
– What makes a piece “good” and another painting “bad”? 
– Why an art critic elaborates over one piece but disregards another? 
– Is an artwork good if it meets some special criteria, or does it depend on who you speak to?', 'After asking professionals for their opinions, I was excited to see what they had to say, but I was surprised to find that no one could agree on a single definition.', 'Some consider the commitment of the artist as the key to good art, while others state good art sticks in your mind as a positive memory, others say it has to do with originality, some say the background story of a piece is the key. There are considerations that it may be up to chance whether a piece becomes popular. However popular does not mean good. While looking for this information one cannot find a single definition that exists.', 'You may get disappointed over the issue. Even professionals often couldn’t decide what made a piece of art good. You are left wondering how could you do it? In the end, one realizes that viewing art is an entirely personal experience based on your knowledge of the style, piece, artist, visual etc.
The interpretation gets into action through personal experience. Often what one person loves, another may find mediocre, one finds depressing, the other may find it inspirational.', 'The beauty of the world lies in this diversity of opinion about everything including art. What may seem to overwhelm some, works differently for others and this difference in reactions only make art even more exciting.', 'There are multiple elements that put together form beautiful art in the viewer’s eyes, and finding out why makes up the journey. The elements may be diverse as memories, experiences, the story of the work, of the artist, his life, or the particular lighting in the gallery, weather, mood etc.', 'For another, it is the criticism, colors, form, texture, description, combined with memories or experiences, or events that make them reflect on a piece. So most probably, deciding the quality of a work of art is very personal, and one has to realize that there is no universal definition. More, the art will lose its power if one-day humanity decides to define what has to be a collective legacy.', 'The best choice would be to see art as a personal experience and adventure. The world of art is made up of multiple genres, mediums, styles, messages, techniques and for sure one can browse and find a connection that will lead him to a new exploration, a step forward into the unknown.', 'One can bring his personal experiences, biases, beliefs, likes, and dislikes, and mix them with the stories, colors, feelings, histories, a new discovery.', 'What is important to understand that by attending an art gallery, walking into a museum, one makes the decision to step into the undiscovered world, full of excitement, something beautiful and profoundly yours.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-makes-good-art/qotw0207/', '2021-02-07T12:00:00Z', '2021-02-07T12:00:00Z'),
  ('l7092', 'what-does-it-mean-to-truly-listen', 'cnscsns', 'name', null, array['Despite being commonly connoted to the auditory sense, ‘listening’ is actually quite different from ‘hearing’. ‘Listening’ is really not attached to any sense in particular, and is rather a state of mind that manifests THROUGH our senses. We can thus listen with our eyes, mouth, nose, and touch, as well as well as with our ears. However, most of the time, we are not actually ‘listening’ but perceiving through a default mode of distraction and reaction. To ‘truly listen’ means to ‘practice’ experiencing one’s immediate reality as it truly is, rather than through old, habitual lenses. I say ‘practice’ because nobody is perfect at this, and there will always be distractions. But to ‘truly listen’ is an energy of intention – it is the intention to be non-judgmentally present with one’s immediate experience, and to come back to this practice when distractions arise. This intention – this energy – is palpable and contagious, and opens the frame for miracles to manifest themselves.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-does-it-mean-to-truly-listen/what-does-it-mean-to-truly-listen/', '2021-02-13T12:00:00Z', '2021-02-13T12:00:00Z'),
  ('l7088', 'what-does-it-mean-to-truly-listen', 'caren-o', 'name', null, array['When sitting face-to-face in conversation with someone—a friend, child, partner, or work colleague—how frequently are you actually thinking about nothing else other than the words that are coming out of the other person’s mouth? Probably not too often. And you are not alone.', 'Research shows that only about 10 percent of us listen effectively. We are so distracted by the cacophony of dings and tweets from our smartphones, not to mention our ever-growing to-do lists, that we struggle to focus and listen when people talk to us. And if we’re not distracted by technology, our own thoughts can keep us from listening to another person. We often think that we are listening but we’re actually just considering how to jump in to tell our own story, offer advice, or even make a judgment—in other words, we are not listening to understand, but rather to reply.', 'Active listening is an essential skill and one of the best ways to connect with another person. The good news is that it is a skill that can be improved with some effort. It also bears noting that there’s a distinct difference between hearing and listening. Hearing is a physiological act; listening involves our ability to unpack the meaning of words, and the silences in between.', 'Dutch writer and professor Henri Nouwen once wrote:', '“Listening is much more than allowing another to talk while waiting for a chance to respond…The beauty of listening is that, those who are listened to start feeling accepted, start taking their words more seriously and discovering their own true selves. Listening is a form of spiritual hospitality by which you invite strangers to become friends.”', 'Why be an active listener?', 'Research has found that active listening helps us focus on understanding others and also improves our relationships by promoting trust, reducing conflict, and increasing our ability to motivate and inspire those with whom we’re communicating. Listening to people’s stories, along with sharing our own, can prompt us to put our attention into another person’s world, which cultivates connection.', 'There are a variety of ways we can become better listeners. Here are just 5:', '1. Practice.', 'The following exercise takes only four minutes, but it will prepare you for what active listening feels like so you can put it into action in your everyday encounters: Find a willing participant. Then face each other with no distractions other than a watch or a timer. For two minutes, one of you will speak, answering a prompt while the other listens. If you’re the listener, do not respond at all during the two minutes, but feel free to use facial expressions or nod your head while listening. The idea is to listen to the words for the sake of listening, not for the sake of replying. Then, switch roles for another two minutes. The prompt to use in the exercise: How are you?', '2. Start from a place of open-mindedness and acceptance.', 'Many of us routinely judge what others say and think about what advice to offer as we hear them speak. Avoiding these patterns will enable you to focus more on what the person is saying, and less on your own interpretation. Before entering into a conversation, ask yourself the following questions:article continues after advertisement', '• Can I stay fully present and listen deeply?', '• Can I keep from judging what the other person is saying?', '• Can I refrain from offering advice?', '• Can I avoid interpreting this person’s experience?', '3. Be attentive but relax your gaze.', 'The idea behind active listening is not to strain your eyes or concentrate too hard, but to be aware of the speaker in a natural and focused way. It’s best to block out distractions—surrounding sounds and activities—that might otherwise grab your attention. If someone’s speech pattern or accent starts to catch your attention, bring your focus back to the words themselves.', '4. Listen to both the words and the silence in between.', 'Most of us are uncomfortable with pauses and what we may consider awkward silences. But in those pauses, we can reflect on the meaning of what a person has just said. Try to keep your mind from wandering during those moments of silence; there may be significance behind the pause itself.', '5. Ask open-ended questions.', 'When it feels appropriate to engage in a response, ask questions that are open-ended, such as: What was that like? and How did that feel? It will make for a better dialogue and give you the chance to continue gaining information.', 'Everyone has something to say, a story to tell, and words we can learn from. I encourage you to listen—really listen—to those around you, whether the speaker is someone you know well or a new personal or professional acquaintance. You never know where someone else’s words may lead you.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-does-it-mean-to-truly-listen/qotw0214-4/', '2021-02-13T12:00:00Z', '2021-02-13T12:00:00Z'),
  ('l7084', 'what-does-it-mean-to-truly-listen', 'gaia', 'name', null, array['Let’s face it: Most people aren’t good listeners. In fact, most people — including your best friend who truly loves you to the moon and back — are terrible listeners. But it’s not their fault. No one (well, very few people) are out here trying to ignore your important thoughts and problems. They want to help, but listening is hard.', 'So, what’s the issue? Well, first off, no one actually teaches us how to listen to others. And, second, when we are taught about listening, it’s often presented as a passive skill, something that you do while allowing your eyes to glaze over and your mind drift off until you have an opportunity to speak again. And if that sounds like you — even a little bit — you’re not alone. Right now, people all over the world are feeling not listened to while their friends, parents, significant others, and all other manner of acquaintances are sitting there wondering “what the hell?”', 'Don’t beat yourself up over past mistakes, though. All you need to know is this: Like any other skill, listening well takes time and practice. And in order to help you communicate better, we enlisted the help of Vanessa Marin, a licensed psychotherapist who’s seen just about everything (check out her previous conversations with us here and here) to give us a primer on how to stop just hearing and start really learning how to buckle down and listen to the people in your life.', 'Slowwwwwwwww Dowwwwwwwn', 'SHUTTERSTOCK', 'Here’s the thing: bad listeners — those who just want to jump into the conversation as soon as a moment presents itself — aren’t typically trying to one-up or hurt the people they’re speaking with. “One of the communication patterns I’ve seen most frequently, in the US in particular, is that we’re all really quick to want to help another person, and think that we understand them,” Marin says.', 'While this doesn’t sound at all bad (who doesn’t want to be understood?) Marin points out that the problem arises when we’re in such a rush to connect with another person — to show the that we “get it” — that we stop paying attention and jump right into reciprocal sharing; that is, we start describing an experience we’ve had that’s parallel to the one that’s being discussed, as an attempt to show understanding.', '“We can be so desperate to get to that moment of connection that we often end up cutting the other person off prematurely,” Marin adds. “I see a lot of jumping to conclusions; or the speaker is halfway through the sentence, and you’re like, ‘Oh, no, no, no, I got it, I got it, I know where you’re going already.’”', 'The problem? You usually don’t now where the other person is going. And even if you do, the jumping in will often feel like an interruption rather than a genuine moment in which you and the speaker truly feel each other.', '“Slow down, and really let the person get their full thought out before responding,” Marin says. “Often, when we think we’re listening, what we’re actually doing is planning our response. You can’t do both of those things at the same time. It just occupies too much brain space.” That means you may think you’re listening (and your intentions could be 110 percent pure) but you’re actually doing a pretty crappy job of it.', 'Is there an easy fix to this? Yep, but you’re going to have to be more mindful of how you communicate. First, slow down and stop thinking about your responses while you’re listening. Your goal isn’t to force a connection or help someone — that comes later — but to show the person that what they’re saying is important. So allow yourself to chill out, focus on the other person, and then ask questions instead of jumping in with your own personal experience.', '“You don’t have to get to that place of ‘I get it,’” so quickly,” Marin says. “It’s okay to have a little uncertainty.”', '“Really be thoughtful about letting the person finish their full sentence,” Marin adds, “and maybe even let there be a little bit of an awkward pause at the end, just so you can fully make sure that they’re saying what it is they needed to say. If you’ve interrupted somebody, that’s a tell-tale sign that you’re not doing a good job of listening, you’re jumping ahead a little too much.”', 'Ask Questions', 'Think about your goals when you’re listening to someone. Is it to let someone vent? To solve a problem? To tell your friend how to properly live her life so the problems that are befalling her right now don’t befall her again? All these things may be true — you sound like a really great friend, BTW — but they’re also secondary to allowing the other person to know they’ve been heard. So resist the urge to preach and get interested instead.', '“I think a lot of it is trying to take this mindset of genuinely being curious about what’s going on in another person’s head,” Marin says. “A lot of us start to get this idea that when you know somebody really well you know what’s going on in their head, and the reality is that we never know what’s going on in another person’s head, like ever. Truly ever.”', 'In order to combat this, Marin suggests cultivating what she calls “a beginner’s mind.”', '“It’s trying to get to this place of feeling more curiosity, and more of the unknown of really trying to get a sense of, ‘what’s going on in that person’s brain?’ ‘How are they stringing their thoughts together?’ ‘What’s coming up for them in this moment?’” she says. “And the only way you can do that, to truly be curious and show whoever you’re speaking to that you’re hearing them, is to squelch the impulse to share or rescue and start asking questions instead.”', 'There are two types of questions you could ask: The first type is content-based, so ask the person you’re listening to “tell you more.” If they’re feeling a particular type of way, ask them about another time they’ve felt that way before and what it was like. Feel free to be openly curious about the situation the other person is going through, without being judgmental — so maybe avoid questions like ‘why did you do that?’ and go for more questions like ‘and what happened next?’ or ‘how do you feel about that?’ There’s also the old stand-by of ‘well, how are you feeling right now?’ which Marin says you shouldn’t just write off. Sometimes, just asking a person to explain how they feel in the moment can be a powerful way to foster connection.', 'The second type of question? It’s the kind that you may have learned about in a communications class you took your freshman year. “A good way to ask questions is the old psychology trick of trying to repeat back what you think that you heard,” Marin says. “So just try saying like, ‘Okay, is this what you’re saying? I think I understand. Is it this?’ That can be a really good way to gauge if you’re hearing right.”', 'This allows the other person to let you know if you’re actually getting them (we’re often wrong!) and lets you get a good sense of whether you’re picking up on what they’re saying.', 'Of course, you should use these types of questions in moderation, lest the speaker think you’re just reciting lines that you’ve learned (it gets more natural with practice) and, Marin adds, it’s totally okay to call yourself out if it’s clear that you and the speaker are completely missing each other when it comes to whether you’re understanding or not.', '“I think we’re all desperate to be listened to,” Marin says, “so if we get a sense that the other person is really making a genuine effort, and they really care, nobody’s going to complain and be like, ‘No, I don’t want to explain that to you again.’ As long as you’re having that good attitude about it, and the person understand that your motivations are pure.”', '“I think a lot of us have that natural reaction to want to jump into problem-solver mode, especially when it’s somebody that you really care about,” Marin continues. “You don’t want to see them hurting, or dealing with something difficult, so a great question that you can ask is, ‘what do you need from me around this, do you need to just talk about it? Do you want me to help you brainstorm some solutions? Do you want me to take the lead and do something?’”', '“If you were able to hear from that person, ‘hey, I need you to just listen right now,’ then that would instantly put you more into that mindset, where you’re not having pressure on your shoulder of, ‘Oh God, I have to listen to him, and understand what he’s saying, andI need to come up with the perfect solution to how to make him not feel this way.’”', 'Make the Conversation more Manageable', 'If you’ve ever been in a relationship (of any kind), you know that fights are inevitable. And once you start fighting — and most of us aren’t taught how to argue correctly, either — the conversation often turns into a flurry of accusations, allegations, and rehashes of old arguments that happened three years ago but seem pertinent now. Bringing all that up? It’s not going to win you any accolades or a quick make-up.', 'Marin says that when we’re arguing or discussing a sensitive issue, it feels like one person unloads and then the other feels like it’s their turn to be vent about the ills of the world before they’re interrupted again. Does that work? Marin says no. Instead, she suggests breaking the conversation down into tiny, manageable pieces and allowing both parties to agree they’re on the same page before moving on to the next part of the issue. In this way, both people are heard and no one feels like their needs are being ignored.', 'This might also be a good time to break out the email and text communication. No, Marin’s not suggesting you start messaging your friends to see if you’re right — that’s just going to add fuel to the flame — but she says that electronic communication can be a good way to start a conversation about a sensitive topic, and it ensures that whoever’s the listener has to take in the entire message before responding.', 'Of course, there’s some stigma when it comes to texting and emailing — and Marin says you should definitely put down your devices when you go from chatting your problems to talking face-to-face — but it’s a good way to begin a discussion that may be difficult. And if you know that you’re someone who gets anxious when another person has a lot to say, saying ‘can we email about this so I’m absolutely positive I’m getting everything you want to say?’ isn’t wrong or shameful.', 'In fact, it can ultimately be incredibly beneficial.', 'Get Past how you were Socialized', 'If you’ve ever seen the comments section of a piece about good communication skills, then you know that the responses are often full of people suggesting that men, in particular, have a hard time listening without jumping to problem-solving right away. It’s just one of those things that guys do, these people argue, and there’s no use in trying to change that.', '“Men are definitely socialized to do something with their emotions,” Marin says, “whereas women are socialized to have more permission to just have emotions, and just feel them. Men are programmed to believe that it’s not okay for a man to just sit around and feel his emotions, you have to do something with them, or get rid of them in some way.”', '“I think that, that’s a message that all men get, on pretty much a daily basis from the time that they can even understand what’s going on, so it’s definitely an understandable, automatic place to go to,” she adds.', 'But is that reason enough to not be a good listener? Absolutely not. In fact, Marin says that if you’re listening to someone you truly care about — a significant other, say — and they tell you that all they need is for you to be present and to listen, that there’s no one who’s incapable of just chilling out and doing just that — even if you have the perfect solution to the problem that you’re being told about. “It just takes a little bit of intention,” Marin says.', 'Intention is Paramount', 'When you’re listening, it’s going to take some effort to not immediately jump into thinking, talking, and helping mode. But, as mentioned before, what you see as helping may feel like a rude interruption to the person you’re listening to.', '“I think that something to really have in the back of your mind is, ‘all I need to do is just listen to this person, and be there for them, be there right here in this moment with them here right now,’” Marin says. “I think that’s probably the biggest mind shift that most of us could stand to have.”', 'Will it feel weird at first? Sure. But that’s because most of us have never actually given ourselves the freedom to listen to another person. We’re so caught up in the act of fixing that we often discount how much effort true active listening takes. And listening takes a lot of effort. That’s why there are actual courses in active listening, why there are countless books on the subject, and why even the most seasoned therapists — those who get paid to listen — often need to remind themselves that listening can be difficult.', '“I definitely remember doing these exercises in my intro psych courses,” Marin says. “You think, ‘okay, this is so easy, I just sit here and listen,’ and then you realized what an incredible effort goes into actually, actively listening to someone. Even now, after sessions, I think, ‘wow, that took a lot of energy, to just sit there and listen.’”', 'It’s important, she adds, to recognize that this listening isn’t just something you do passively.', '“It’s so rare that we’re actually, truly listening, Marin says, “that we should realize that it really is a skill, it’s something that takes a lot of effort to do.”', 'So pay attention to body language, tone of voice, what the person’s face is telling you. How is the other person speaking? Do they sound tense or anxious? If you’re truly listening, you’re taking all that into account, and that leaves much less space for you to focus on other things (like what you’re going to say next, or what you’re planning to have for dinner).', 'Want some practice? Marin recalls an exercise from grad school that really helped her. And it might help you, too. All you need to do is choose a reality show — it doesn’t matter which — turn off the sound and watch people communicate. It may sound a little silly, but because reality TV is so over the top, Marin says, it helps you pick up on what people are really feeling. That can help you be more perceptive of how people feel in situations not brimming with drama.', 'And here’s another exercise: Put down your phone and get off Facebook when you’re listening to someone. You may think you’re able to listen to your partner’s latest gripes about work — god knows, we all have them — while you’re scrolling through your Facebook feed, Marin says, but you’re not nearly as good at multi-tasking as you’d like to believe you are. Plus, either way, the person who’s speaking will feel more heard if your attention is solely focused on them and not on a google search about what the hell was happening in Arrival that everyone else got and you didn’t. (There were a lot of plot holes, right?)', 'Accept that it’s okay to be Bored', 'Our lives aren’t reality shows, so you already know that sometimes you’ll have conversations that are plebeian, pedestrian, banal, and every other synonym of “boring” you can think of. That’s why it is so easy to think you can check your Twitter, play Bejeweled, and pay attention to whatever someone’s telling you all at once. But here’s the thing: You can’t tune out just because you’re not interested. And that goes double if you’re in a relationship or have a close friendship you’d like to maintain.', '“There are lots on mundane conversations that you’re going to have that are not thrilling in any way,” Marin says. “I think there are two approaches that you can take: on the one hand you can try to see if there’s a way to get yourself more engaged, so maybe asking questions, trying to get a little more detail. Maybe your husband starts working on a cool project that catches your attention more than other projects he’s worked on. There are ways to find a little bit more of a hook for you in it.”', '“The other piece of it,” she adds, “is just recognizing that there are absolutely going to be lots of conversations that are not going to be exciting. That’s where it’s good to remember that you don’t need to do anything when you’re listening, sometimes that person just wants to be heard, they just want to share what happened in their day, or tell you about the project. But they don’t need you to come up with any solutions or have some amazing understanding of it, or anything like that, it’s just normal day-to-day conversations.”', 'Yes, this does turn that whole adage about “great minds discussing ideas” onto its head, but real life is much more complex than a Facebook post your aunt shared once. And think about it this way: Marin points out that while you may be bored by what your friend, family member, or partner has to say about their work day (especially if you’re not in the same industry and have no idea what’s going on), they’ve probably had to deal with the same feeling when it’s your turn to talk.', 'That’s not to say you’re boring, of course, but a reminder that there are things that you may be interested in or care about that the other person just doesn’t get. It’s all about perspective, so recognize that no relationships are like the ones they show on TV — the crying and the screaming and the making up and the thrilling betrayals that happen second by second — and make an effort to respect the other person’s right to be listened to just because they’re a human being that you care about.', '“There’s something there about just having a sense of goodwill with each other and recognizing that nobody’s ever trying to be boring, or mundane,” Marin says. “When we’re communicating with another person, especially with our partners, we’re trying to connect with them, we’re trying to have some time with them, just have some moments of intimacy and connection. Even if there are times when one of us brings up something that’s kind of boring, and not the most exciting thing, recognizing that, at the root of that, it’s just a desire for connection, that’s a really and special thing, even if the topic itself is HR memos.”', 'And there’s one more benefit to listening well: When you listen to another person well, and they feel truly heard, they’ll listen to you when it’s your turn to speak. Is it going to take some practice? Absolutely. But in the end, Marin says, it’s a win-win.']::text[], null, 'live', false, false, false, 'https://quarxtheories.com/qotw/what-does-it-mean-to-truly-listen/qotw0214-3/', '2021-02-13T12:00:00Z', '2021-02-13T12:00:00Z'),
  ('l7081', 'what-does-it-mean-to-truly-listen', 'kenneth-v', 'name', null, array['Do you believe you are a good listener and do others agree?', 'If you don’t have that reputation, it’s not your fault: your brain is designed to predict what other people are going to say next. You are often so busy listening to your brain’s plotting and planning that you can’t hear what the other person is saying.', 'A study conducted at Princeton University found that “speaker–listener neural coupling underlies successful communication”. If that was so much Greek to you, let’s state it more simply: when your brain starts acting like your conversational companion’s brain, you actually communicate. You won’t be surprised to hear that the study found there is generally a lag between what you hear and what you understand, and this is where we get into trouble. In the midst of that lag, we start predicting and supposing and guessing. Too often, we are still caught up in our own reverie as our conversation partner continues talking. The good doctors at Princeton would say that our brain activities decouple at that point and that as a result comprehension starts to plummet. This is the scientist’s way of saying, “You’re not listening.”', 'Training Your Pet Brain', 'The good news is that your brain works for you: rather than letting it just do what it’s programmed to do automatically, you can train it to do new tasks. The brain is the best pet you could ever hope for—it can be taught all kinds of tricks, and it loves to please its master. The trick to teaching your pet brain is concentration. Many folks find concentration to be taxing but that is because they approach it in the wrong way. While you can make yourself concentrate, sooner or later you will tire out and your brain will go back on autopilot. The result will be “neural decoupling”—that is, your brain will wander off on its own.', 'Concentration is more properly approached passively rather than actively. Don’t make yourself concentrate; allow yourself to concentrate. Just hear what is said, observe the nonverbal cues like facial expressions and body language, absorb the tone and the pace of their speech. If you find you are distracted by other stimuli or by your own thoughts, be gentle with yourself. Just guide yourself back to hearing with no self-judgment. In fact, recognize that self-judgment itself is just another distracting thought. You will find with practice that these wanderings become less frequent.', 'When you first attempt this, you will notice that you respond less quickly in conversation. People may not be used to you being this contemplative, so give them the chance to get used to it. Your responses will be more in tune with them, and everybody likes “in tune” better than “out of tune”. In short, they will feel heard by you like they have never felt it before.', 'Brain Pattern Alignment', 'If you do this, something fascinating happens, according to the doctors at Princeton. They did fMRI brain scans of the participants in their study and found that people’s brain wave patterns started to align as people actually listened. Not only did the lag between hearing and understanding vanish but the listeners started to anticipate what the other person was about to say before they said it. This is not the same as your autopilot guesses; instead, what they found is your brain pattern actually starts to match that of your partner in real time. When that happens, a strong connection occurs, understanding deepens between you, and real communication takes place.', 'When you as the listener find yourself in the same state at the talker, you tend to move in tandem. People get a real charge out of being understood, so it is very much worth your effort to seek such an alignment. There is the practical benefit of receiving information as its imparter meant it to be received and additionally there is also an emotional connection that takes place. Even in mere business or transactional settings, there is value to such an emotional connection as it fosters trust and comfort. As a result, people believe in your sincerity and genuineness, which eases relations and lessens conflict.', 'Your brain may not be so good at listening but that doesn’t mean you can’t be. Let it know who the boss is, and earn the reputation of being a good listener.']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-does-it-mean-to-truly-listen/qotw0214-2/', '2021-02-13T12:00:00Z', '2021-02-13T12:00:00Z'),
  ('l7078', 'what-does-it-mean-to-truly-listen', 'john-h', 'name', null, array['I believe that the ability to truly listen is one of the most important skills we can develop in this life—as leaders, as husbands and wives, as friends and coworkers. Here’s a question I have asked in numerous workshops over the past few months: How many of you have had formal training in listening? It never fails to stun me when only about 10 percent of the attendees raise their hands. Listening is such a critical skill—and yet so few have been trained in how to do it. Here is a short course.', 'What does it mean to really listen?', 'Dictionary.com defines the word listen as follows:', 'lis·ten [lis–uhn] verb', '1. To give attention with the ear; attend closely for the purpose of hearing', '2. To pay attention; heed', 'Yes, it means to hear; but it also means to pay attention—with our ears, our eyes, and our hearts.', 'Listen to more than the words', 'True listeners look beyond the words themselves—they search for meaning in the speaker’s tone and body language. This is especially important when the communication has an emotional component.', 'A study done by Dr. Albert Mehrabian at UCLA looked at the degrees to which emotional messages are sent through words, tone, and body language. Regarding the true meaning of an emotional message, Dr. Mehrabian found:', '• 7 percent of meaning is in the words that are spoken', '• 38 percent of meaning is in the tone of voice—the way the words are said', '• 55 percent of meaning is in facial expression', 'If what we are hearing is different from what we are sensing from the tone or the facial expression, guess which one is correct!', 'Show You Are Listening', 'Part of really listening is responding in a way that shows the other person we are paying attention. We can demonstrate we are truly listening in four different ways. For example, if a coworker comes to you and complains about their micromanaging boss, you could show you are listening by:', '• Reflecting back the content', 'Example: As you see it, your boss is micromanaging you…', '• Reflecting back the feeling', 'Example: So you feel frustrated because…', '• Reflecting both content and feeling', 'Example: You feel frustrated because your boss is micromanaging you…', '• Being silent and attentive', 'A helpful phrase to show you are listening might be:', 'So you feel ___________________ because ______________________.', 'Other helpful phrases might include:', '• You seem…', '• You sound…', '• What I’m hearing is…', '• As you see it…', '• Tell me more…', '• Is there anything else…', 'Not only is listening to others a key life skill, it can also have a tremendous impact on building trust in a relationship. When we take the time to listen, we show the other person that we care—that we are interested in understanding their perspective. That can go a long way toward building, or rebuilding, a relationship.”', '“The purpose of life is to listen – to yourself, to your neighbor, to your world and to God and, when the time comes, to respond in as helpful a way as you can find … from within and without.” ~ Fred Rogers', '“A good listener is not only popular everywhere, but after a while he knows something.” ~ Wilson Mizner']::text[], null, 'live', false, false, true, 'https://quarxtheories.com/qotw/what-does-it-mean-to-truly-listen/qotw0214/', '2021-02-13T12:00:00Z', '2021-02-13T12:00:00Z')
on conflict (id) do nothing;
